// Behavioral evidence: pinned 1.1.0 CLI commands/*.rs, repo/*.rs and API handlers.
// Only the Markdown generator consumes these notes; examples are never executed here.
export const pair = (en, zh) => [en, zh];
export const notes = {};
export const permission = {
  member: pair('Platform login, selected project, and membership in that project (including Operator).', '平台登录、已选择项目，并且是该项目成员（包括 Operator）。'),
  editor: pair('Platform login, selected project, and effective project Owner/Admin/Developer. Operator cannot use this command, including its read-only form.', '平台登录、已选择项目，有效项目角色为 Owner/Admin/Developer。Operator 不可用，包括只读形式。'),
  publisher: pair('Platform login, selected project, and effective project Owner/Admin; Developer/Operator cannot publish.', '平台登录、已选择项目，有效项目角色为 Owner/Admin；Developer/Operator 不可发布。'),
  login: pair('A configured server and platform login; no selected project required.', '已配置服务端并完成平台登录；无需选择项目。'),
  session: pair('A platform login session, not a personal access token (PAT); no selected project required.', '平台登录会话，不接受个人访问令牌（PAT）；无需选择项目。'),
  local: pair('No existing platform login or selected project required; local filesystem/process access and the command-specific prerequisites below still apply.', '无需已有平台登录或选择项目；仍须本地文件/进程权限及下述命令专属前提。'),
  admin: pair('Platform Admin/Owner; project role does not grant this platform permission.', '平台 Admin/Owner；项目角色不能赋予此平台权限。'),
  owner: pair('Platform Owner; platform Admin and project Owner alone are insufficient.', '平台 Owner；仅平台 Admin 或项目 Owner 不足。')
};
function add(key, perm, behavior, output, recovery, argv, prerequisite = pair('Use the synthetic names below only in your isolated demo project; replace identifiers with values returned by its list/create commands.', '以下合成名称仅用于隔离演示项目；标识符请替换成该项目 list/create 返回的值。')) {
  notes[key] = { perm, behavior, output, recovery, argv: ['viat', ...key.split(' '), ...argv], prerequisite };
}
const p = pair;
const ID = '00000000-0000-4000-8000-000000000001';
export const dummyId = ID;
add('version','local',p('Prints the CLI release first. If configuration contains a server and login, also tries authenticated GET /version; this is distinct from viat --version, which never asks the server.','先打印 CLI 版本；若配置中有服务端和登录，再尝试认证 GET /version。与从不访问服务端的 viat --version 不同。'),p('stdout: viat 1.1.0 (cli), optionally a server line or an unavailable/not-signed-in explanation. Minor-version mismatch warns on stderr. Server lookup failure still exits 0.','stdout 为 viat 1.1.0 (cli)，可附服务端行或不可用/未登录说明。次版本不同在 stderr 警告。服务端查询失败仍退出 0。'),p('Compare CLI/server minor versions before sync. Nothing to undo; the authenticated request may refresh the local session.','同步前比较 CLI/服务端次版本。无需撤销；认证请求可能刷新本地会话。'),[]);
add('auth login','local',p('Password mode needs --email AND --password at runtime; --oidc selects browser login instead. Password MFA accepts --totp or prompts, at most five attempts on one ticket. Enrollment-required must be completed in the console. OIDC prints a browser URL and polls every 2s for up to 5 minutes.','密码模式运行时同时需要 --email 和 --password；--oidc 选择浏览器登录。密码 MFA 使用 --totp 或提示输入，同票最多五次。要求注册 MFA 时必须在控制台完成。OIDC 打印浏览器 URL，每 2 秒轮询、最多 5 分钟。'),p('stdout: logged in as <email>. Saves access/refresh tokens to the resolved .viat/config.yaml; does not select a project. Same-server ancestor sessions are reused; different-server login creates a CWD session unless VIAT_CONFIG_DIR is explicit.','stdout: logged in as <email>。将 access/refresh token 保存到解析出的 .viat/config.yaml；不选择项目。同服务端复用祖先会话；换服务端会在 CWD 新建会话，除非显式 VIAT_CONFIG_DIR。'),p('Invalid credentials/MFA, expired browser flow, or enrollment requirement exit 1. Check server URL and enroll in the console rather than repeatedly retrying credentials (rate limits apply). Use auth logout for local clearing; protect config.yaml and avoid real passwords in shell history.','凭据/MFA 错误、浏览器流程超时或要求注册均退出 1。核对 URL 并在控制台注册，不要反复重试（有速率限制）。用 auth logout 清理本地登录；保护 config.yaml，勿把真实密码写入历史。'),['--server','http://127.0.0.1:28080','--email','operator@example.invalid','--password','demo-only-not-a-real-password'],p('An existing platform account on an isolated instance. The literal dummy password only illustrates syntax; it is not a working shipped credential. OIDC also requires a configured platform OIDC provider and browser access.','隔离实例上的现有平台账号。示例密码仅演示语法，不是产品预置凭据。OIDC 还需配置平台 OIDC 提供方并能打开浏览器。'));
add('auth whoami','login',p('GET /auth/whoami with the console credential; does not report a project end-user identity.','以控制台凭据 GET /auth/whoami；不是查询项目终端用户身份。'),p('stdout contains the signed-in email only; 0 on success.','stdout 仅输出已登录邮箱；成功退出 0。'),p('Expired unrefreshable login exits 1: log in again, then repeat. No project changes or cleanup.','会话过期且无法刷新时退出 1：重新登录再查。无项目变更，无需清理。'),[]);
add('auth logout','local',p('Clears legacy token, access/refresh tokens, refresh expiry and current_project in the resolved config. This implementation makes no server revocation call and leaves server_url and project_token untouched.','清除配置中的旧 token、access/refresh token、刷新到期时间和 current_project。实现不调用服务端撤销，并保留 server_url 与 project_token。'),p('stdout: logged out; 0 if config save succeeds, even without a live server.','stdout: logged out；配置保存成功即退出 0，不需要在线服务端。'),p('Save failure exits 1; fix filesystem permissions. For actual session/PAT revocation use the appropriate server account controls; remove a residual project_token from protected local config if it must not remain. Re-login and select the project to resume.','保存失败退出 1；修复文件权限。真正撤销会话/PAT 应使用服务端账号管理；若不应保留 project_token，请从受保护本地配置中移除。恢复使用需重新登录并选择项目。'),[]);
add('auth token create','session',p('POST /auth/tokens; --project restricts scope, omission means all projects the user can access. Runtime --ttl default is 30d; humantime durations such as 12h work; --ttl never sends zero for no expiry. Durations are truncated to whole seconds: avoid subsecond durations that become zero/no expiry. The account still supplies the authority: a PAT is not a role grant.','POST /auth/tokens；--project 限定项目，省略表示用户可访问的所有项目。运行时 --ttl 默认 30d，接受 12h 等 humantime 时长；--ttl never 发送零表示不过期。时长截断到整秒，避免不足一秒被转为零/不过期。权限仍来自账号：PAT 不授予角色。'),p('Text prints metadata AND the one-time Secret; --json prints the response including secret. Capture securely; success exits 0.','文本打印元数据及仅显示一次的 Secret；--json 返回含 secret 的响应。须安全保存；成功退出 0。'),p('Bad TTL/name/scope or PAT-authenticated attempts fail. If output is lost, revoke this token by ID and mint another; auth token list cannot recover the secret.','TTL/名称/范围无效或用 PAT 管理令牌会失败。若输出丢失，请按 ID 撤销重建；auth token list 无法恢复秘密。'),['--name','demo-ci','--ttl','12h']);
add('auth token list','session',p('GET /auth/tokens for the current platform account, not other accounts or api_key authorizers.','GET /auth/tokens，仅列当前平台账号，不是其他账号或 api_key authorizer 的 key。'),p('Table: name, project, prefix, created, expiry, last-used and status; --json returns the items object. No secret. Text status is best-effort (its expired comparison is not a reliable current-time expiry check); use expiry timestamps.','表列名称、项目、前缀、创建/到期/最后使用时间及状态；--json 返回 items 对象，无秘密。文本状态为尽力判断（expired 比较不是可靠的当前时间判断）；应查看到期时间。'),p('PAT authentication is refused; use a login session. Read-only apart from normal refresh persistence; no cleanup.','PAT 认证被拒绝；使用登录会话。除常规刷新持久化外只读，无需清理。'),['--json']);
add('auth token revoke','session',p('UUID is used directly; other strings are resolved among non-revoked token names. Zero matches or multiple matching names refuse instead of choosing arbitrarily. DELETE /auth/tokens/{id}.','UUID 直接使用；其他字符串按未撤销 token 名称解析。零匹配或重名均拒绝，不随意选择。DELETE /auth/tokens/{id}。'),p('stdout: Revoked token: <id-or-name>; success 0. Secret stops authorizing; revocation is not local logout.','stdout: Revoked token: <id-or-name>；成功 0。秘密不再授权；撤销不是本地退出。'),p('For ambiguous names, list and supply an ID. Revocation cannot be undone: create a replacement and update consumers. Verify with auth token list --json.','重名时 list 并使用 ID。无法撤销此操作：创建替代 token 并更新调用方。用 auth token list --json 核查。'),[ID]);
add('project list','login',p('GET /projects lists only projects the caller can access; platform rank alone does not supply project membership.','GET /projects 仅列调用者可访问的项目；平台级别不自动赋予项目成员身份。'),p('Text shows slug, display name and * on selected project; --json emits the server list. Empty list is successful.','文本显示 slug、显示名和所选项目的 *；--json 输出服务端列表。空列表也成功。'),p('Missing projects require membership, not repeated select attempts. No mutation or cleanup.','缺少项目需取得成员身份，不是反复 select。无变更，无需清理。'),['--json']);
add('project create','login',p('POST /projects creates a remote-only project and makes the creator Owner. Does not scaffold files or select it. Slug and display name are separate positional values.','POST /projects 仅创建远程项目，创建者成为 Owner。不生成文件、不选择项目。slug 与显示名是两个位置参数。'),p('stdout confirms created project; 0 after successful response.','stdout 确认创建项目；响应成功后退出 0。'),p('Duplicate/invalid slug fails without creating another project. Verify project list; select explicitly. Delete an unwanted demo project through the console/API (there is no project delete CLI leaf).','slug 重复/无效时失败，不创建第二个。用 project list 验证并显式 select。不需要的演示项目通过控制台/API 删除（CLI 无 project delete）。'),['cli-demo','CLI Demo']);
add('project select','login',p('Checks slug against GET /projects, then saves current_project in the resolved local config. It does not cd, pull, scaffold, or mint a project token.','先以 GET /projects 核对 slug，再在本地配置保存 current_project。不切目录、不 pull、不生成目录，也不签发项目 token。'),p('stdout: selected cli-demo; success 0. Local selection changes subsequent project-scoped commands.','stdout: selected cli-demo；成功 0。本地选择会影响后续项目命令。'),p('Unknown/inaccessible slug exits 1 and is not selected. Verify project list; select the previous slug to undo.','未知/不可访问 slug 退出 1，不会选中。用 project list 核查；选回原 slug 即可恢复。'),['cli-demo']);
add('project init','login',p('Creates the remote project and a local repo (default ./<slug>, --here uses CWD). Runtime --name defaults to slug. --here permits only .git/.idea/.claude/.vscode/.viat; otherwise refuses nonempty dirs. Writes .viat/config.yaml, viat.yaml and endpoints/scripts/workflows/schedules/watches/ws_triggers/resources directories. --server overrides destination, not login authority.','创建远程项目和本地仓库（默认 ./<slug>，--here 用 CWD）。运行时 --name 默认为 slug。--here 仅容许 .git/.idea/.claude/.vscode/.viat，其余非空目录拒绝。写入配置、viat.yaml 和 endpoints/scripts/workflows/schedules/watches/ws_triggers/resources 目录。--server 只覆盖目的地，不提供登录权限。'),p('Prints remote creation, scaffold path and selected project. New repo config selects the project. No push or publish occurs.','打印远程创建、目录和项目选择；新仓库配置选中项目。不执行 push/publish。'),p('Not transactional across remote/filesystem: failures can leave a directory or created project. Inspect both before retrying; do not blindly delete a non-demo project. Remove disposable local scaffold and delete the remote demo through console/API when done.','远程与文件系统不是同一事务：失败可能留下目录或项目。重试前两边核查；勿盲删非演示项目。用完删除演示本地目录，并通过控制台/API 删除远程演示项目。'),['cli-demo','--name','CLI Demo']);
add('project diff','member',p('Compares CWD repository content to remote drafts, not publish state or a push request plan. --only validates kinds; crate is not supported. Script/workflow/resource server-only items are informational because push does not delete them.','比较 CWD 仓库与服务端草稿，不是发布状态或 push 请求计划。--only 校验类别，不支持 crate。仅服务端存在的脚本/工作流/资源只是信息，因为 push 不删这些。'),p('Text marks added/removed/changed/server-only; --json gives stages with added, removed, changed and server_only arrays. --exit-code exits 1 for real differences, not informational server_only; otherwise differences still exit 0.','文本标记新增/移除/修改/仅服务端；--json 为各阶段 added/removed/changed/server_only 数组。--exit-code 仅真实差异退出 1，server_only 不算；不带该项有差异也退出 0。'),p('Run from a complete repo root and select intended project. Unknown kind fails; read permissions for metadata may require editor. Resolve draft drift before push; no remote changes to undo.','在完整仓库根执行并核对项目。未知类别失败；元数据读取可能需 editor。push 前解决草稿差异；没有远程变更需撤销。'),['--only','scripts,workflows','--exit-code']);
add('project folderize','publisher',p('Dry-run by default; --apply performs a server-side transactional prefix-to-folder rename with reference rewrites while preserving UUIDs. Repeated --prefix selects legacy prefixes. This requires project Owner/Admin.','默认预览；--apply 在服务端单事务中将前缀改为文件夹并重写引用，保留 UUID。可重复 --prefix。要求项目 Owner/Admin。'),p('Prints planned/applied moves and rewrites; --json returns plan/result. Published snapshots do not change until republish.','打印计划/已执行的移动和重写；--json 返回计划/结果。已发布快照须重新发布才变。'),p('Collisions refuse instead of overwriting. Review dry-run, then apply and pull: local old filenames are stale. There is no inverse folderize option; retain a backup and explicitly rename/rewrite to undo.','冲突时拒绝，不覆盖。先审查预览，再 apply 并 pull：旧本地路径已过时。无反向 folderize 选项；保留备份并显式重命名/重写恢复。'),['--prefix','legacy','--json']);
add('project member ls','member',p('GET selected project /members; project collaborators are platform accounts, not p-user rows.','GET 所选项目 /members；协作者是平台账号，不是 p-user 行。'),p('Text: email, role, display name or (no members); --json preserves user_id and timestamps.','文本为邮箱、角色、显示名或 (no members)；--json 保留 user_id 与时间戳。'),p('403 means no membership. Obtain access from a project Owner/Admin; read-only, no cleanup.','403 表示不是成员。向项目 Owner/Admin 申请；只读，无需清理。'),['--json']);
add('project member add','publisher',p('Adds an existing platform email with independent project owner/admin/developer/operator role. CLI normalizes role case. This does not invite an unregistered account.','把现有平台邮箱加入项目并授予独立 owner/admin/developer/operator 角色。CLI 规范化角色大小写。不会邀请未注册账号。'),p('Text: <email> added to <slug> as <role>; --json prints response. Membership is effective immediately.','文本: <email> added to <slug> as <role>；--json 打印响应。成员身份立即生效。'),p('Unknown email fails: use user invite --project with --role for a new account. Verify member ls; member rm removes demo membership, subject to last-owner guard.','邮箱不存在则失败：新账号用 user invite --project 并带 --role。用 member ls 验证；用 member rm 移除演示成员，受最后 Owner 保护。'),['teammate@example.invalid','--role','developer']);
add('project member set-role','publisher',p('PUT member role by email. Project role is independent of platform user set-role. Cannot demote the last project Owner.','按邮箱 PUT 成员角色。项目角色独立于 user set-role 平台角色。不能降级最后项目 Owner。'),p('Text: <email> is now <role> in <slug>; --json prints response. Access changes immediately.','文本: <email> is now <role> in <slug>；--json 打印响应。权限立即改变。'),p('Promote another Owner before demotion; invalid/nonmember email fails. Record original role and restore with set-role; verify member ls.','降级前先提升另一 Owner；邮箱无效/非成员会失败。记录原角色并用 set-role 恢复；member ls 验证。'),['teammate@example.invalid','operator']);
add('project member rm','publisher',p('DELETE membership by email, including self if another Owner remains. Removes that membership’s push-device registrations; rejoining does not restore registrations. Cannot remove the last Owner.','按邮箱 DELETE 成员；若另有 Owner 可移除自己。同时删除该成员项目推送设备注册；重新加入不会恢复注册。不能移除最后 Owner。'),p('Text: <email> removed from <slug>; --json prints {ok:true}. Project access is lost immediately.','文本: <email> removed from <slug>；--json 打印 {ok:true}。立即失去项目访问。'),p('Last-owner refusal needs another Owner first. Re-add with original role to restore membership, and re-register devices separately. Platform account itself is not deleted.','最后 Owner 拒绝时先添加其他 Owner。以原角色重新 add 恢复成员，设备需另行注册。不删除平台账号本身。'),['teammate@example.invalid']);

// Resources: direct create/edit YAML is an API payload, not a repo-sync file.
add('workflow list','member',p('Lists current workflow drafts across folders.','列各文件夹当前工作流草稿。'),p('Text: qualified name and vN; --json emits server list; empty list succeeds.','文本为限定名和 vN；--json 输出服务端列表；空列表成功。'),p('Use qualified references from this list. No execution/mutation or cleanup.','使用列表限定引用。不执行、不修改，无需清理。'),['--json']);
add('workflow show','member',p('Reads one draft, not the snapshot served by published endpoints.','读单个草稿，不是已发布端点快照。'),p('Text prints # name (vN) and YAML definition; --json returns public workflow object.','文本打印 # name (vN) 及 YAML 定义；--json 返回公开工作流对象。'),p('Missing/ambiguous name fails; qualify folder. Save this definition before update/delete if rollback is needed; reading itself needs no cleanup.','名称不存在/歧义会失败；限定文件夹。若需回退，update/delete 前保存此定义；只读本身无需清理。'),['demo_flow','--json']);
add('workflow create','editor',p('Reads raw YAML --file and POSTs name/folder/definition. Names may be folder-qualified. Creates a draft only, no run/publish.','读取原始 YAML --file，POST name/folder/definition。名称可含文件夹。只建草稿，不执行/发布。'),p('stdout: created <name> (vN). Server validates the workflow definition and referenced structure.','stdout: created <name> (vN)。服务端校验定义及引用结构。'),p('Invalid YAML/definition or duplicate name fails. Verify workflow show; delete demo_flow when no longer referenced.','无效 YAML/定义或重名会失败。workflow show 验证；无引用时删除 demo_flow。'),['demo_flow','--file','demo-workflow.yaml'],p('A valid workflow YAML definition in demo-workflow.yaml; use the minimal fixture in this page. Its referenced demo_echo script must already exist.','demo-workflow.yaml 须为有效工作流 YAML；使用本页最小夹具。其引用的 demo_echo 脚本须已存在。'));
add('workflow update','editor',p('PATCHes the whole definition from --file, creating a new draft version. Published endpoints stay on old snapshots until publish.','从 --file PATCH 完整定义，产生新草稿版本。发布前端点保持旧快照。'),p('stdout: updated <name> → vN and any pending-endpoint hint.','stdout: updated <name> → vN，附可能的待发布提示。'),p('Definition validation failures exit 1. Preserve previous YAML, verify show, test only with opt-in to real effects; restore previous definition to undo draft changes.','定义校验失败退出 1。保留旧 YAML、show 核查；仅明确允许真实副作用后 test；恢复旧定义回退草稿。'),['demo_flow','--file','demo-workflow.yaml']);
add('workflow delete','editor',p('Deletes saved workflow draft. Does not undo runs or their resource side effects.','删除保存的工作流草稿，不撤销执行及资源副作用。'),p('stdout: deleted <name>; 0 after successful DELETE.','stdout: deleted <name>；DELETE 成功 0。'),p('Remove dependent schedules/endpoints deliberately first and keep YAML. Confirm absence with list; recreation requires the saved definition, not old run logs.','先有意移除依赖调度/端点并保留 YAML。list 确认不存在；重建需保存定义，不能靠旧日志。'),['demo_flow']);
add('workflow test','editor',p('POSTs live unpublished definition to /test_run using --input JSON (default {}, alias --args). Runs real resources and may mutate them.','以 --input JSON（默认 {}，别名 --args）向 /test_run 执行在线未发布定义。访问真实资源并可修改。'),p('Per-attempt step statuses go to stderr. Only when user_error is null AND no step_runs row has status failed does stdout print outputs and exit 0. ANY failed attempt row exits 1, even when a retry later succeeded or the runtime recovered the overall result.','逐尝试步骤状态写 stderr。仅 user_error 为 null 且 step_runs 没有任何 failed 行时 stdout 打印 outputs 并退出 0。任一失败尝试行都退出 1，即使后来重试成功或运行时恢复整体结果。'),p('On failure prints request_id, user_error and failed-step errors to stderr, not success outputs. Inspect logs with that ID before deciding to rerun; repeating can duplicate writes. No automatic resource rollback.','失败时 stderr 打印 request_id、user_error 和失败步骤错误，不打印成功 outputs。用该 ID 查日志再决定重跑，重复执行可重复写入。不自动回滚资源。'),['demo_flow','--input','{}']);
for (const verb of ['create','update']) add(`schedule ${verb}`,'member',p(`${verb === 'update' ? 'Full PUT upsert, not a partial patch' : 'Creates a schedule'}: exactly one --cron/--every-secs AND exactly one --script/--workflow are required at runtime. --inputs must be a JSON object. Defaults enabled=true and inputs={}; --disabled saves paused. No per-schedule timezone/retry/endpoint-target flags are exposed here.`,`${verb === 'update' ? '完整 PUT upsert，不是部分更新' : '创建调度'}：运行时 --cron/--every-secs 必选其一，--script/--workflow 必选其一。--inputs 须为 JSON 对象。默认 enabled=true、inputs={}；--disabled 保存为暂停。未暴露逐调度时区/重试/端点目标参数。`),p(`stdout: ${verb === 'create' ? 'created' : 'updated'} <name>. An enabled schedule can subsequently execute real target side effects; saving is not a draft/publish flow.`,`stdout: ${verb === 'create' ? 'created' : 'updated'} <name>。启用后可执行真实目标副作用；保存不走草稿/发布流程。`),p('Invalid trigger, missing target, nonobject inputs or target absence fails. Unlike content editing, these API mutations require only membership in this version. Verify schedule show; pause/delete demo_tick when done. For update preserve the entire previous trigger/target/inputs/enabled state before replacement.','触发器无效、缺目标、非对象输入或目标不存在会失败。本版本这些 API 写入不同于内容编辑，只需成员身份。用 schedule show 验证；用完 pause/delete demo_tick。update 前保存完整旧 trigger/target/inputs/enabled。'),['demo_tick','--every-secs','3600','--script','demo_echo','--disabled']);
add('schedule list','member',p('Reads saved operational schedules, not repo YAML or publish snapshots.','读已保存的运行调度，不是仓库 YAML 或发布快照。'),p('Text: name, active/paused, trigger, target, next_due; --json returns rows.','文本为名称、active/paused、触发器、目标、next_due；--json 返回行。'),p('No selected project/permission causes failure. Empty list is success, not scheduler health proof. Read-only; no cleanup.','未选项目/无权限会失败。空列表成功，不证明调度器健康。只读，无需清理。'),['--json']);
add('schedule show','member',p('Reads one schedule including inputs, enabled state and execution pointers.','读单个调度，含输入、启用状态及执行指针。'),p('Text: name, status, trigger, target, inputs, next_due, last_fired, last_run; --json gives full object.','文本为 name/status/trigger/target/inputs/next_due/last_fired/last_run；--json 完整对象。'),p('404 is not a paused schedule: check list. Follow last_run into execution logs to verify effects, not just next_due. No mutation/cleanup.','404 不是暂停：查 list。跟随 last_run 查执行效果，不只看 next_due。无变更/清理。'),['demo_tick','--json']);
add('schedule pause','member',p('Disables future automatic scheduling; does not cancel an already-running execution.','禁用后续自动调度，不取消正在运行执行。'),p('stdout: paused <name>; server returns changed row.','stdout: paused <name>；服务端返回变更行。'),p('Missing schedule fails. Verify show status paused; resume restores scheduling but recomputes next_due rather than old due time.','不存在则失败。show 确认 paused；resume 恢复时重算 next_due，而非旧到期时间。'),['demo_tick']);
add('schedule resume','member',p('Enables the schedule and recomputes cron/interval next_due relative to now, using the stored zone. CLI cannot create once schedules, whose API resume semantics differ.','启用调度并相对现在重算 cron/interval 的 next_due，使用已存时区。CLI 不能创建 once 调度，其 API resume 语义不同。'),p('stdout: resumed <name> (next_due now: <timestamp>). Automatic real executions may follow.','stdout: resumed <name> (next_due now: <timestamp>)。之后可发生真实自动执行。'),p('Check show next_due and inputs before resuming. Pause again to stop future runs; past/in-flight side effects are not reversed.','恢复前 show 核查 next_due 和输入。再 pause 可停止后续执行，但不会撤销已发生/进行中的副作用。'),['demo_tick']);
add('schedule trigger','member',p('Fires the saved target once manually, separately from the schedule’s future due time; can execute real effects even when used for diagnostics.','手动触发已存目标一次，与未来到期独立；即使诊断也可发生真实副作用。'),p('stdout contains the bare request_id only. Exit 0 reports accepted trigger response, not necessarily eventual runtime success.','stdout 仅裸 request_id。退出 0 表示触发响应成功，不必然是最终运行成功。'),p('Use logs show <request_id> to inspect completion before retrying. Do not retry blindly after connection loss; repeated triggers can duplicate mutations. No automatic undo.','用 logs show <request_id> 查完成后再重试。断连后勿盲试；可重复变更。无自动撤销。'),['demo_tick']);
add('schedule delete','member',p('Deletes scheduling configuration, not previously emitted executions or target scripts/workflows.','删除调度配置，不删除已发出执行及目标脚本/工作流。'),p('stdout: deleted <name>; DELETE handles the server’s empty 204 response.','stdout: deleted <name>；DELETE 可处理服务端空 204 响应。'),p('Missing name fails. Verify list; recreate from saved full schedule if required. Deletion cannot recall a running job.','名称不存在失败。list 验证；需要时从完整保存配置重建。删除不能召回运行中任务。'),['demo_tick']);

for (const verb of ['list','show']) add(`testcase ${verb}`,'member',p(verb === 'list' ? 'Lists saved regression cases for one folder-qualified script/workflow target; --kind defaults to script.' : 'Reads a saved regression case by UUID, including exact stored args and expected output.',verb === 'list' ? '列某个限定脚本/工作流目标的已保存回归用例；--kind 默认 script。' : '按 UUID 读已存回归用例，包括准确 args 和 expected。'),p(verb === 'list' ? 'Text shows count, on/off, case name, UUID and match mode; --json emits array.' : 'Text shows name, target, enabled, match, args and expected; --json emits object.',verb === 'list' ? '文本含数量、on/off、名称、UUID 和 match；--json 为数组。' : '文本含 name/target/enabled/match/args/expected；--json 为对象。'),p('These reads do not execute the target or validate current output. Missing case/invalid kind fails. No remote mutation; treat captured args/output as potentially sensitive.','这些读取不执行目标，也不验证当前输出。用例不存在/kind 无效会失败。无远程变更；保存的 args/输出可能敏感。'),[verb === 'list' ? 'demo_echo' : ID,'--json']);
add('testcase create','editor',p('Stores target/name/args/expected and subset or exact matching. --args must be an object; expected is JSON, not a file path. Enabled cases gate future publish apply and run the live target, not offline fakes. Saving does not run the target now.','保存 target/name/args/expected 与 subset/exact 比较。--args 须对象；expected 是 JSON，不是文件路径。启用用例会阻挡未来 publish apply 并执行在线目标，非离线假资源。保存本身不立即运行。'),p('Text: created test case <name> (UUID); --json prints created case.','文本: created test case <name> (UUID)；--json 打印创建行。'),p('Bad JSON/match, duplicate case or invalid target fails. Save returned UUID, show it, then explicitly opt in to testcase run. Cleanup testcase delete <id>; disabling retains data but stops the gate.','JSON/match 错误、用例重名或目标无效会失败。保存 UUID 并 show，明确允许后再 run。清理用 testcase delete <id>；disable 保留数据但不再阻挡。'),['demo_echo','demo_ok','--expected','{"ok":true}','--json']);
add('testcase update','editor',p('Partial PUT sends only supplied --name/--args/--expected/--match. At least one is required. Does not change target binding or run it.','部分 PUT 只发传入 --name/--args/--expected/--match，至少一项。不改目标绑定、不执行。'),p('Text: updated test case <id>; --json returns updated object.','文本: updated test case <id>；--json 返回更新对象。'),p('Invalid JSON/match/no flags fails; preserve previous expected/args so a mistaken change does not weaken the gate. Verify show; restore those values with update to undo.','JSON/match/无选项会失败；保存旧 expected/args，避免误改削弱门槛。show 核查；再 update 旧值回退。'),[ID,'--expected','{"ok":true}']);
add('testcase run','editor',p('Runs the case now against live draft target and real resources; this is not script test or endpoint test.','立即针对在线草稿目标和真实资源跑用例；不是 script test/endpoint test。'),p('Text PASS/FAIL/ERROR/SKIPPED plus mismatch paths; --json emits outcome. Only outcome passed exits 0; skipped, failed, errored or any other outcome exits 1.','文本为 PASS/FAIL/ERROR/SKIPPED 及不匹配路径；--json 返回 outcome。仅 passed 退出 0；skipped/failed/errored/其他均 1。'),p('Inspect mismatch vs runtime error before updating expected. Re-running can repeat business writes; no automatic undo. Use isolated resource fixtures and clean their data with explicit opt-in.','改 expected 前区分不匹配与运行错误。重跑可重复业务写入，无自动撤销。使用隔离资源夹具，明确授权后清理其数据。'),[ID,'--json']);
for (const verb of ['enable','disable']) add(`testcase ${verb}`,'editor',p(`${verb === 'enable' ? 'Enables' : 'Disables'} this saved case as a publish regression gate. Does not run it and does not remove expected/args.`,`${verb === 'enable' ? '启用' : '禁用'}此保存用例的发布回归门槛。不运行，不移除 expected/args。`),p(`Text: ${verb === 'enable' ? 'enabled' : 'disabled'} test case <id>; --json emits updated row.`,`文本: ${verb === 'enable' ? 'enabled' : 'disabled'} test case <id>；--json 返回更新行。`),p(`Missing UUID fails. Verify testcase show; ${verb === 'enable' ? 'disable' : 'enable'} reverses the toggle. ${verb === 'disable' ? 'A disabled guard can let a bad publish through; record why it is disabled.' : 'Future publish can now execute this live target, so review its effects first.'}`,`UUID 不存在会失败。testcase show 核查；用 ${verb === 'enable' ? 'disable' : 'enable'} 反转。${verb === 'disable' ? '禁用门槛可放过坏发布，应记录原因。' : '未来发布会执行在线目标，应先审查副作用。'}`),[ID]);
add('testcase delete','editor',p('Removes one saved regression case and therefore its future publish gate; does not delete the target or run history.','删除一个保存用例及未来发布门槛，不删除目标/执行历史。'),p('Text: deleted test case <id>; --json emits server response.','文本: deleted test case <id>；--json 输出服务端响应。'),p('Keep show output for rollback; missing ID fails. Verify list; recreate with original args/expected/match and restore enabled state (new UUID).','保留 show 输出回退；ID 不存在失败。list 核查；用原 args/expected/match 重建并恢复启用状态（UUID 会变）。'),[ID]);
add('endpoint list','editor',p('Lists draft endpoint nodes, not a runtime request. Text is a narrowed view; use --json for IDs and publish-status metadata.','列草稿端点节点，不是运行时请求。文本是缩减视图；ID/发布状态元数据须用 --json。'),p('Text: method/DIR, path, script binding, authorizer names/inherit and type.action gates/inherit (not UUIDs). --json gives full list. This read requires editor, unlike script list.','文本为 method/DIR、path、script 绑定、authorizer 名称/inherit 和 type.action gate/inherit（无 UUID）；--json 完整列表。此读取需 editor，不同于 script list。'),p('Missing access fails even if other project reads work. Use returned UUIDs in endpoint commands; no mutation or cleanup.','即使能读项目其他内容，无此权限仍失败。后续端点命令用返回 UUID；无变更/清理。'),['--json']);
add('endpoint show','editor',p('Reads a draft node by UUID and its effective configuration; UUID is not a route path or script name.','按 UUID 读草稿节点及有效配置；UUID 不是路由路径/脚本名。'),p('Default text is pretty JSON of the narrowed EndpointView (id,parent,segment,method,script,path,authorizers,gates,override flags); --json emits the raw full server object, including additional target/publish fields.','默认文本为缩减 EndpointView 的格式化 JSON（id/parent/segment/method/script/path/authorizer/gate/override）；--json 输出服务端完整对象，包含额外目标/发布字段。'),p('Wrong project or nonexistent UUID fails. Capture before edits; show is not proof that current callers serve the draft. No cleanup.','项目/UUID 错误会失败。编辑前保存；show 不证明线上调用已使用草稿。无需清理。'),[ID,'--json']);
add('endpoint create','editor',p('Creates a draft branch or leaf with --segment, optional parent/tree, method and script/workflow binding. --tree resolves UUID/name. --authorizers repeats one name per flag; commas are not split by this command. It cannot express CRUD/proxy/authz-gate configuration through this leaf; use repo/console API instead.','创建草稿分支/叶，使用 --segment、可选 parent/tree、method 和 script/workflow。--tree 可解析 UUID/名称。--authorizers 每次一名称，可重复；本命令不按逗号拆分。此命令不能表达 CRUD/proxy/authz gate 配置；使用仓库/控制台 API。'),p('stdout: created <method-or-DIR> <path>, then id: <UUID>. No published route is activated.','stdout: created <method-or-DIR> <path>，再 id: <UUID>。不激活发布路由。'),p('Reserved platform paths, invalid parent/segment/target combinations and missing tree fail. Verify list/show and publish intentionally. Delete the disposable leaf by returned ID to clean up.','保留路径、父节点/segment/目标组合无效、tree 不存在会失败。list/show 验证后有意发布。清理时用返回 ID 删除演示叶。'),['--segment','demo','--method','GET','--script','demo_echo']);
add('endpoint update-auth','editor',p('PUTs draft allowed_authorizers plus override flags. Nearest declared authorizer list replaces ancestors; authz gates accumulate until override_permissions stops the walk. This command has no retired permissions flag and does not expose editing gates. Omitted override booleans are sent false. Omitting --authorizers sends null and RESETS the local list to inherit; it does not preserve it. Repeat --authorizers for multiple names (no comma splitting). Existing authz_gates are preserved because this CLI does not send that field.','PUT 草稿 allowed_authorizers 和 override。最近声明认证器列表替换祖先；authz gate 累加到 override_permissions 停止。无旧 permissions 参数，也不编辑 gate。省略 override 布尔仍发送 false。省略 --authorizers 会发 null，将本地列表重置为继承，并非保留。多个名称重复 --authorizers（不拆逗号）。CLI 不发送 authz_gates，已有 gate 保留。'),p('stdout: updated auth for <path>. Runtime snapshot stays unchanged until publish; children may inherit a changed draft.','stdout: updated auth for <path>。发布前运行时快照不变；子节点可继承草稿变化。'),p('Unknown authorizer/built-in protected node fails. Inspect old effective auth first and preserve configuration; restore auth, then republish affected endpoints if the change shipped.','未知认证器/受保护内建节点会失败。先检查旧有效认证并保存；若已交付，恢复认证并重发受影响端点。'),[ID,'--authorizers','demo_password']);
add('endpoint update-info','editor',p('PUT sends only provided segment/method/script keys; --clear-method and --clear-script send explicit null. It cannot rebind every target kind (no workflow/resource replacement flag here).','PUT 只发送提供的 segment/method/script；--clear-method/--clear-script 显式发 null。不能重绑所有目标类型（无 workflow/resource 替换参数）。'),p('stdout: updated info for <path>; modifies draft identity/binding, not active snapshot.','stdout: updated info for <path>；改草稿标识/绑定，不改活跃快照。'),p('Clear flags are NOT parser conflicts: when a value and its clear flag are both supplied, clear wins. Invalid resulting branch/leaf states can still fail server validation. Save show output, verify the resulting node, publish intentionally; restore previous fields and publish to undo served changes.','clear 不是解析冲突：同时传值和其 clear 标记时以 clear 为准。结果分支/叶状态无效仍可在服务端校验失败。保存 show 输出，核查节点后有意发布；回退旧字段并发布以撤销线上变更。'),[ID,'--segment','demo-renamed']);
add('endpoint delete','editor',p('Deletes a node; branch deletion cascades descendants and can remove their active routes. Not merely an unpublish operation. Built-in auth nodes are protected.','删除节点；分支级联删除子节点，可移除活跃路由。不只是 unpublish。内建 auth 节点受保护。'),p('stdout: deleted <id>; 0 after successful DELETE.','stdout: deleted <id>；DELETE 成功 0。'),p('Back up repo/definitions and inspect descendants first. Verify endpoint list and routing; recreation requires new nodes and deliberate publish, not a simple rollback of this deletion.','先备份仓库/定义、检查后代。用 list 与路由验证；重建需新节点和有意发布，不是简单 rollback 删除。'),[ID]);
add('endpoint publish','publisher',p('Publishes this leaf’s draft snapshot and builds dependencies. Warning/regression refusals are overridden only by respective --acknowledge-* flags; no confirmation prompt. Changes served routing.','发布此叶草稿快照并构建依赖。仅相应 --acknowledge-* 可越过警告/回归拒绝；不询问确认。改变线上路由。'),p('Prints published METHOD path as vN, build ok/FAILED and optional environment-pending note. A successful publish response containing failed builds is still CLI exit 0: inspect lines, not only exit code.','打印 published METHOD path as vN、build ok/FAILED 与可选环境待构建说明。成功发布响应即使含失败 build，CLI 仍 0：须检查行，不只退出码。'),p('Warnings/tests refuse with HTTP errors; fix or explicitly acknowledge after review. Test cases can call real resources. Verify history and an authorized route request; rollback restores prior snapshot but does not undo external test/build effects.','警告/测试可通过 HTTP 错误拒绝；修复或审查后显式确认。用例可访问真实资源。history 和经授权路由验证；rollback 恢复旧快照，不撤销外部测试/构建效果。'),[ID]);
add('endpoint unpublish','publisher',p('Removes this leaf’s active snapshot from routing but keeps draft/history.','从路由移除此叶活跃快照，保留草稿/历史。'),p('stdout: unpublished <id>; changes live availability.','stdout: unpublished <id>；立即影响线上可用性。'),p('Nonleaf/protected/missing endpoint fails. Verify history/show; publish intentionally to restore service (current draft may differ from the removed snapshot).','非叶/受保护/不存在端点会失败。history/show 核查；有意 publish 恢复（当前草稿可不同于刚移除快照）。'),[ID]);
add('endpoint rollback','publisher',p('Restores the preceding endpoint snapshot, not an arbitrary version argument. Does not restore current draft or rewind external databases.','恢复上一个端点快照，不接受任意版本参数。不恢复当前草稿、不回退外部数据库。'),p('stdout: rolled back to vN (<snapshot-id>); immediately changes served route content.','stdout: rolled back to vN (<snapshot-id>)；立即改变线上路由内容。'),p('No earlier snapshot/nonleaf/missing endpoint fails. Read history before and after; a later publish uses the current draft, so inspect it before reapplying.','无前快照/非叶/不存在端点会失败。操作前后读 history；之后 publish 使用当前草稿，重发前先检查。'),[ID]);
add('endpoint history','publisher',p('Reads snapshot history for one endpoint. Unlike project publish history, this read requires publisher rights.','读单端点快照历史；不同于项目 publish history，此读取需 publisher。'),p('Text rows: vN, method (or *), path and script/workflow@version when present. No --json option.','文本行含 vN、method（或 *）、路径及可用的 script/workflow@version。无 --json。'),p('Missing/nonleaf UUID fails. Use this to verify publish/rollback versions; no mutations or cleanup.','UUID 不存在/非叶会失败。用于确认发布/回滚版本；无变更/清理。'),[ID]);
add('endpoint purge-cache','publisher',p('POSTs cache/purge to invalidate this endpoint’s cached responses on all instances; does not delete the endpoint or change its cache configuration.','POST cache/purge，跨实例失效此端点响应缓存；不删端点、不改缓存配置。'),p('stdout: purged the cached responses of <id>. Subsequent matching GETs can hit runtime again.','stdout: purged the cached responses of <id>。后续匹配 GET 可重新执行运行时。'),p('Requires existing endpoint and publisher, not just editor. Verify with authorized requests/cache telemetry; no inverse cache-fill operation and no undo for runtime effects triggered afterward.','需端点存在及 publisher，只有 editor 不足。用授权请求/缓存指标核查；无反向填缓存命令，之后触发运行效果不可撤销。'),[ID]);
add('endpoint test','local',p('Runs endpoint fixtures (default endpoint_tests/) through a scratch instance’s real dispatch with fake resources. Seeds/pushes/publishes this local repo in the scratch server. Requires a dedicated base PostgreSQL URL in VIAT_ENDPOINT_TEST_DB and matching viat-endpoint-test-host. Not the signed-in server.','通过临时实例真实 dispatch 和假资源运行端点夹具（默认 endpoint_tests/）。在临时服务端植入/push/publish 本地仓库。需 VIAT_ENDPOINT_TEST_DB 专用基础 PostgreSQL URL 和匹配 viat-endpoint-test-host，不是登录服务端。'),p('Streams host/fixture results and returns nonzero for failures; no fixtures does not prove coverage. Host version is checked before dispatch.','流式输出 host/夹具结果，失败返回非零；无夹具不证明覆盖。dispatch 前检查 host 版本。'),p('Creates then drops a scratch database; use an isolated PostgreSQL account allowed to create/drop databases, never production. Check host diagnostics if startup/cleanup fails; remove only the named scratch DB after confirming no process uses it. Test code itself still needs review for external calls.','创建后删除临时数据库；使用有建库/删库权限的隔离 PostgreSQL 账号，不用生产。启动/清理失败查 host 诊断，确认无进程使用后仅删指定临时库。测试代码本身仍需审查外呼。'),['endpoint_tests']);
add('tree list','editor',p('Lists endpoint tree containers; an editor is required even for this read.','列端点树容器；此读取也需 editor。'),p('Text shows id, name and path_override; --json returns list. Root override is displayed distinctly.','文本含 id/name/path_override；--json 列表。根覆盖单独显示。'),p('Do not confuse trees with filesystem directories or script folders. No mutation/cleanup; use IDs/names here for tree show/update.','树不是文件系统目录/脚本文件夹。无变更/清理；show/update 使用此处 ID/名称。'),['--json']);
add('tree show','editor',p('Accepts UUID or exact tree name; names are resolved by listing current project trees.','接受 UUID 或精确 tree 名；按当前项目树列表解析名称。'),p('Text: id, name, path_override; --json returns raw tree object.','文本 id/name/path_override；--json 原始树对象。'),p('Unknown name/UUID fails rather than creating a tree. Save original name/path before edits; reading needs no cleanup.','名称/UUID 未知失败，不会创建。改前保存原 name/path；读取无需清理。'),['demo_tree','--json']);
add('tree create','editor',p('Creates a tree with required --name and --path override; --path is a URL prefix, not local folder. Server validates uniqueness/path shape.','以必填 --name 和 --path 覆盖建树；--path 是 URL 前缀，不是本地目录。服务端校验唯一性/形状。'),p('stdout lines: id, name, path_override. No endpoint execution or automatic publish.','stdout 为 id/name/path_override。不执行端点、不自动发布。'),p('Duplicate/invalid path fails. Verify tree show; delete empty demo tree when done, after inspecting its endpoint descendants.','路径重复/无效失败。tree show 验证；用完先查子端点，再删空演示树。'),['--name','demo_tree','--path','/demo']);
add('tree update','editor',p('PATCHes provided --name and/or --path after resolving UUID/name; absent fields remain unchanged. Renaming the tree is not moving script/resource folders.','解析 UUID/名称后 PATCH 提供的 --name/--path，省略字段不变。树改名不是移动脚本/资源文件夹。'),p('stdout: id, name, path_override. Review endpoint draft paths and publish state after path changes.','stdout: id/name/path_override。改路径后检查端点草稿路径及发布状态。'),p('Name/path collisions refuse; keep original values and restore via update. Verify tree show plus endpoint list; changes to served snapshots require the appropriate publish operation.','名称/路径冲突拒绝；保存旧值并 update 恢复。tree show 与 endpoint list 核查；线上快照变更需相应发布操作。'),['demo_tree','--name','demo_tree_renamed']);
add('tree delete','editor',p('Resolves UUID/name and deletes the tree, potentially cascading its endpoint subtree. Treat as destructive routing change, not deletion of an empty local directory.','解析 UUID/名称并删树，可级联其端点子树。视为破坏性路由变更，不是删空本地目录。'),p('stdout: deleted <name> (<UUID>); handles empty DELETE response.','stdout: deleted <name> (<UUID>)；支持空 DELETE 响应。'),p('Inspect children and back up endpoint repo first; any currently published node causes 409 conflict refusal: unpublish deliberately first. Verify list; recreation and republishing are explicit and old IDs need not survive.','先检查子节点并备份端点仓库；若任一节点已发布，会以 409 conflict 拒绝，须先有意取消发布。list 验证；重建和发布须显式，旧 ID 不保证保留。'),['demo_tree']);
add('publish plan','member',p('Lists project-wide publishable dirty leaves and draft-vs-active summaries. Server also heals stale dependency-closure dirty markers; this does not activate routes.','列项目可发布脏叶与草稿/活跃摘要。服务端也修复依赖闭包过期 dirty 标记；不激活路由。'),p('Text shows target/version/status/diff; --json returns plan with publishable_count. Empty plan exits 0.','文本含目标/版本/状态/差异；--json 返回含 publishable_count 计划。空计划退出 0。'),p('Plan is not a reservation: concurrent edits may change apply. Read-only to callers apart from internal marker repair; no rollback needed. Review real test/build side effects before apply.','计划不是预留：并发编辑可改变 apply。除内部标记修复外对调用者只读，无需回退。apply 前审查真实测试/构建副作用。'),['--json']);
add('publish apply','publisher',p('Publishes all dirty endpoints atomically as one revision. Prompts unless --yes or --json; declining prints Aborted and exits 0. --require-tests runs local script test first. Enabled server regression cases run against real resources; warnings/test failures block the whole batch unless corresponding --acknowledge-* is given.','以单版本事务发布全部脏端点。无 --yes/--json 则询问；拒绝打印 Aborted 并退出 0。--require-tests 先跑本地 script test。已启用服务端回归用例跑真实资源；警告/失败阻止整个批次，除非相应 --acknowledge-*。'),p('Text lists snapshots/build results or Nothing to publish. --json prints raw response/refusal body, exit 1 for non-2xx. Build failures/pending reported inside an accepted publish response do not themselves cause CLI nonzero; routes can be live while installs fail/run.','文本列快照/构建结果或 Nothing to publish。--json 原样打印响应/拒绝体，非 2xx 退出 1。已接受发布内的构建失败/待构建本身不导致 CLI 非零；安装失败/进行中路由也可已生效。'),p('Fix failing cases/warnings rather than automatically acknowledging them. Inspect history/show, build/env and authorized smoke requests. publish rollback restores the head revision’s snapshots, not resources, schema or test side effects.','应修复用例/警告，不自动确认。核查 history/show、build/env 和授权冒烟请求。publish rollback 只恢复最新版本快照，不回退资源、schema 或测试副作用。'),['--yes']);
add('publish rollback','publisher',p('Rolls back the latest project publish revision, including endpoints previously unpublished. Does not accept an arbitrary revision parameter. Prompts unless --yes/--json; decline exits 0.','回滚最新项目发布版本，包括原先未发布端点。不接受任意版本参数。无 --yes/--json 则询问；拒绝退出 0。'),p('Text prints restored snapshot/unpublished per endpoint; --json gives response. No revision in prompted mode prints Nothing to roll back and exits 0.','文本逐端点打印恢复快照/未发布；--json 返回响应。询问模式无版本时打印 Nothing to roll back 并退出 0。'),p('Inspect history/show before action and verify after. External databases/resources and current drafts are not rolled back. To restore a newer change, inspect draft then publish; do not assume repeated rollback toggles safely.','操作前后检查 history/show。外部库/资源和当前草稿不回退。恢复较新变更前检查草稿再发布；勿假定重复 rollback 安全切换。'),['--yes']);
add('publish history','member',p('Lists project publish revisions with limit/offset; server clamps limit to 1–100 and offset to at least 0.','按 limit/offset 列项目发布版本；服务端 limit 限 1–100，offset 最小 0。'),p('Text revision summary or --json object with total, limit, offset, revisions. Defaults 20 and 0.','文本版本摘要，或 --json 的 total/limit/offset/revisions 对象。默认 20 和 0。'),p('This read needs membership, unlike endpoint history which needs publisher. Paginate for older revisions; no mutation/cleanup.','只需成员，不同于需 publisher 的 endpoint history。旧版本须分页；无变更/清理。'),['--limit','20','--offset','0','--json']);
add('publish show','member',p('Reads one project revision by full UUID or unambiguous prefix; not an endpoint snapshot ID.','以完整 UUID 或无歧义前缀读项目版本，不是端点快照 ID。'),p('Text gives before/after snapshot changes; --json returns revision details.','文本为前后快照变更；--json 完整版本详情。'),p('Missing/ambiguous prefix fails: use full ID from history. Reading does not roll back or publish; no cleanup.','前缀不存在/歧义会失败：用 history 完整 ID。读取不回滚/发布，无需清理。'),[ID,'--json']);
add('authorizer list','editor',p('Lists the selected project’s authorizers, not platform login providers; read is editor-gated.','列所选项目认证器，不是平台登录提供方；读取也需 editor。'),p('Text: name, kind, default-role UUID or -; --json gives public rows/config, never stored provider secrets.','文本含 name/kind/default-role UUID 或 -；--json 公开行/config，不含已存提供方秘密。'),p('No rows is success. Default-role UUIDs are not role names: use role list/show to resolve. No changes/cleanup.','无行也成功。default-role UUID 不是角色名：用 role list/show 解析。无变更/清理。'),['--json']);
add('authorizer show','editor',p('Reads one project authorizer’s public definition.','读取单个项目认证器公开定义。'),p('Text: name, kind, default-role UUID or -; --json also shows public configuration.','文本含 name/kind/default-role UUID 或 -；--json 还含公开配置。'),p('Unknown name fails. Save public config before changes but keep original provider secret separately; show cannot recover it. Reading needs no cleanup.','名称未知失败。变更前保存公开配置，并单独保管原提供方秘密；show 无法恢复秘密。读取无需清理。'),['demo_password','--json']);
add('authorizer create','editor',p('Creates name/kind/default_role with config={}. This leaf has no config/secret input, so jwt/oauth_oidc/social kinds needing config cannot be fully configured here; use console/API or supported repo declarations. anonymous/password/api_key can use optional defaults.','以 name/kind/default_role 和 config={} 创建。无 config/secret 输入，需配置的 jwt/oauth_oidc/social 无法在此完整配置；改用控制台/API 或受支持仓库声明。anonymous/password/api_key 可用可选默认配置。'),p('stdout: created authorizer <name> (<kind>). No user, key or token is minted.','stdout: created authorizer <name> (<kind>)。不签发用户/key/token。'),p('Bad kind/default role or required config fails. Verify show; delete demo authorizer only after unbinding endpoints and reviewing cascading API-key loss.','kind/默认角色错误或缺必需 config 会失败。show 验证；解绑端点并检查级联 key 损失后才删演示认证器。'),['--name','demo_password','--kind','password']);
add('authorizer update','editor',p('Requires --default-role or --clear-default-role; PUT sends only default_role (empty string clears), preserving kind/config/provider secret. Cannot change kind or configure OIDC/JWT here.','必选 --default-role 或 --clear-default-role；PUT 只发 default_role（空字符串清除），保留 kind/config/提供方秘密。不能在此改 kind/配置 OIDC/JWT。'),p('stdout: updated authorizer <name> (<kind>): default_role <role-or-none>.','stdout: updated authorizer <name> (<kind>): default_role <role-or-none>。'),p('No flag/unknown role fails. Record previous role name and restore with update; clear explicitly rather than omitting. Verify show, and review effects on newly resolved client identities.','无选项/角色不存在失败。记录旧角色名并 update 恢复；省略不等于清除。show 验证，审查新解析客户端身份的影响。'),['demo_password','--clear-default-role']);
add('authorizer delete','editor',p('Deletes the project authorizer; api_key keys belong to it and cascade. Endpoint authentication depending on it can break.','删除项目认证器；所属 api_key key 会级联删除。依赖其认证的端点可失效。'),p('stdout: deleted <name>; success 0. This is not token revoke for a single key.','stdout: deleted <name>；成功 0。不是单 key 的 token 撤销。'),p('Inventory bindings/keys first. Deleted key secrets/provider secrets cannot be recovered from pull/show; recreate config and distribute replacement keys explicitly. Verify absence via list.','先盘点绑定/key。删除 key/提供方秘密不能从 pull/show 恢复；须显式重建配置并分发替代 key。list 验证不存在。'),['demo_password']);
add('apikey create','editor',p('Looks up the exact project-user identity (--user) then mints a key under an api_key authorizer. --expires is an absolute server timestamp, not a humantime TTL. Not a platform PAT.','先按 --user 精确查项目用户 identity，再在 api_key 认证器下签发 key。--expires 是绝对服务端时间戳，不是 humantime TTL。不是平台 PAT。'),p('stdout: only the full one-time vsk_<key_id>.<secret> line; stderr: row UUID/key_id/last4 summary. Secret cannot be read back.','stdout 仅完整一次性 vsk_<key_id>.<secret>；stderr 为行 UUID/key_id/last4 摘要。秘密不能读回。'),p('Missing identity/wrong authorizer/invalid expiry fails. Capture securely, do not paste into docs; list then revoke by row UUID to clean up. Lost output requires revoke and remint.','身份不存在/认证器类型错/到期无效失败。安全保存，勿贴文档；清理用 list 的行 UUID revoke。输出丢失需撤销重签。'),['demo_keys','--user','demo_user','--name','demo-client']);
add('apikey list','editor',p('Lists API-key metadata for this api_key authorizer, not the account’s PATs.','列此 api_key 认证器下 key 元数据，不是账号 PAT。'),p('Text columns include UUID, short key_id, name, last4, revoked/active, created. No secret and no --json option.','文本含 UUID、短 key_id、name、last4、revoked/active、created。无秘密，无 --json。'),p('Wrong authorizer kind fails. Copy the first UUID column for revoke, not the short key_id. Read-only; no cleanup.','认证器类型错失败。revoke 用首列 UUID，不是短 key_id。只读，无需清理。'),['demo_keys']);
add('apikey revoke','editor',p('Revokes one API-key row under the given authorizer. The positional key_id name is misleading: it must be the row UUID, not the 12-character key_id in the token.','撤销指定认证器的一个 key 行。位置参数名 key_id 易误导：必须是行 UUID，不是 token 中 12 字符 key_id。'),p('stdout: revoked api_key id=<UUID> at=<time>. Future authorization with this key is denied.','stdout: revoked api_key id=<UUID> at=<time>。后续此 key 认证被拒绝。'),p('Use apikey list to get UUID. No un-revoke CLI: mint a replacement and update consumers; verify list revoked timestamp/status.','apikey list 获取 UUID。无恢复撤销 CLI；重签并更新客户端，list 核查 revoked 时间/状态。'),['demo_keys',ID]);
add('role list','editor',p('Lists project end-user roles, not platform/project collaborator role assignments.','列项目终端用户角色，不是平台/项目协作者角色分配。'),p('Text: role name with builtin/admin tags; --json returns role rows.','文本为角色名和 builtin/admin 标签；--json 角色行。'),p('Requires editor even for reads. Built-in roles are platform-managed and omitted from repo sync; no mutation/cleanup.','读取也需 editor。内建角色由平台管理、仓库同步略过；无变更/清理。'),['--json']);
add('role show','editor',p('Reads a project end-user role; roles carry admin flag/description, not a permission-string list. Authorization rules define data access.','读项目终端用户角色；角色含 admin/描述而非权限字符串列表。数据访问由授权规则定义。'),p('Text: # name with builtin/admin tags; --json returns full public row.','文本为 # name 及 builtin/admin 标签；--json 完整公开行。'),p('Unknown role fails. Use JSON for description/id; no mutation/cleanup.','未知角色失败。描述/id 用 JSON；无变更/清理。'),['demo_role','--json']);
add('role create','editor',p('Creates a non-built-in project role; --admin grants project-end-user administration to everyone assigned this role, not a platform login role. Default admin=false.','创建非内建项目角色；--admin 给所有该角色终端用户项目用户管理权限，不是平台登录角色。默认 admin=false。'),p('stdout: created role <name>, with (admin) tag when true. Does not assign users.','stdout: created role <name>，true 时有 (admin)。不分配用户。'),p('Duplicate/reserved name fails. Verify role show; unassign demo users before delete. Preserve description via repo/console/API because no role update-description CLI exists.','重名/保留名失败。role show 验证；删除前取消演示用户分配。描述通过仓库/控制台/API 管理，无 update-description CLI。'),['--name','demo_role','--description','Synthetic demo role']);
add('role set-admin','editor',p('PUTs boolean --admin true|false on a project role; all users in it gain/lose role-derived project administration. Built-in roles cannot be modified.','以 --admin true|false PUT 项目角色；所有该角色用户获得/失去角色来源项目管理能力。不可改内建角色。'),p('stdout: role <name> admin=<bool>. The account’s own is_admin may still grant access even when role admin=false.','stdout: role <name> admin=<bool>。即使角色 false，用户自身 is_admin 仍可授予权限。'),p('Inspect assignments before elevation. Verify role show and relevant users; restore original boolean to undo. Do not mistake this for user set-role or project member set-role.','提升前检查分配。role show 与相关用户核查；恢复旧布尔回退。不是 user set-role/project member set-role。'),['demo_role','--admin','false']);
add('role delete','editor',p('Deletes a non-built-in project role. This affects user role membership and authorization, not platform accounts.','删除非内建项目角色。影响用户角色与授权，不删除平台账号。'),p('stdout: deleted <name>. Built-in deletion is refused by the API.','stdout: deleted <name>。API 拒绝删除内建角色。'),p('Inventory assigned users and rules, then remove only a demo role. Verify role list; recreating the name does not guarantee old UUID/assignments/rules are restored.','盘点已分配用户和规则，只删演示角色。role list 验证；同名重建不保证恢复旧 UUID/分配/规则。'),['demo_role']);
add('p-user list','editor',p('Reads one page with limit=500, including source/email. CLI has no paging/search flags; --json is still that same page, not all pages.','读取 limit=500 一页，含 source/email。CLI 无分页/搜索参数；--json 仍是该页，不是全部。'),p('Text: identity, source, role_id, display/email/phone and inactive tag, plus truncation hint. --json preserves page object/total.','文本含 identity/source/role_id/显示名/邮箱/电话及 inactive 标记，附截断提示。--json 保留 page/total。'),p('Use console/API ?q=&offset=&limit= for remaining rows. Personal data requires protected captures; no mutation/cleanup.','其余行用控制台/API ?q=&offset=&limit=。个人数据输出需保护；无变更/清理。'),['--json']);
add('p-user create','editor',p('Creates a project end-user identity, optional display-name/role and either plaintext password or imported argon2/bcrypt hash (not both). This is not platform collaborator enrollment.','创建项目终端用户 identity，可选显示名/角色及明文密码或导入 argon2/bcrypt hash（二者不同时）。不是平台协作者加入项目。'),p('stdout: created project user <identity>. Does not print password/hash or log in the new user.','stdout: created project user <identity>。不打印密码/hash、不登录新用户。'),p('Duplicate identity, malformed hash or too-short password (minimum 8 characters) fails. Avoid real credentials in argv; import via protected file for bulk migration. Verify p-user list; delete demo_user for cleanup.','identity 重复、hash 错/密码过短（至少 8 字符）失败。真实凭据勿放 argv；批迁用受保护文件 import。p-user list 验证，delete demo_user 清理。'),['--identity','demo_user','--display-name','Demo User','--role','demo_role']);
add('p-user update','editor',p('PATCHes provided display-name/email/phone/meta; meta is parsed JSON. Omitted fields remain; empty profile strings have API clearing/validation semantics, not a blanket null flag.','PATCH 提供的 display-name/email/phone/meta；meta 解析 JSON。省略保留；空资料字符串按 API 清除/验证，不是通用 null 参数。'),p('stdout: updated <identity> display_name=... email=... phone=.... Does not change credentials or role.','stdout: updated <identity> display_name=... email=... phone=...。不改凭据/角色。'),p('Bad JSON/email/phone fails. Phone validation allows common number punctuation and 5–20 digits; email shape is checked. Save previous profile and restore provided fields; verify list/API.','JSON/邮箱/电话无效失败。电话可用常见符号及 5–20 位数字；校验邮箱形状。保存旧资料再逐字段恢复；list/API 验证。'),['demo_user','--display-name','Demo Renamed','--meta','{"demo":true}']);
add('p-user set-password','editor',p('Replaces the local end-user password with exactly one of --password or --password-hash. Imported hash supports argon2/bcrypt; plaintext must meet the 8-character floor.','以 --password/--password-hash 之一替换终端用户本地密码。导入 hash 支持 argon2/bcrypt；明文至少 8 字符。'),p('stdout: password set for <identity>. Does not expose previous password/hash.','stdout: password set for <identity>。不暴露旧密码/hash。'),p('Missing/both credential flags or bad hash fails. Use synthetic password only in this example; real argv is visible to process listings/history. Verify through an authorized isolated login; restore a securely held credential if needed, never infer old value from output.','无凭据/两种同时或 hash 无效失败。示例仅合成密码；真实 argv 可被进程/历史看到。经授权隔离登录核查；需恢复时用安全保管凭据，不能从输出推导旧值。'),['demo_user','--password','demo-only-password']);
add('p-user import','editor',p('Reads JSON array or JSON Lines; each row identity plus optional password/password_hash/display_name/email/phone/role/meta. Unknown fields are rejected per row. One POST per valid row; continues after failures, no batch transaction.','读 JSON 数组或 JSON Lines；每行 identity，可选 password/password_hash/display_name/email/phone/role/meta。每行拒绝未知字段。有效行逐 POST；失败继续，不是批事务。'),p('stdout: ok/FAILED #row plus <N> created, <N> failed. Any failed row exits 1 after reporting all rows; prior successes remain.','stdout 为 ok/FAILED #行及 <N> created, <N> failed。任一失败行在全部报告后退出 1；先前成功保留。'),p('Keep the input file protected. Reconcile successes before retrying to avoid duplicate-identity failures; delete only created demo identities when cleaning up.','保护输入文件。重试前核对成功行，避免 identity 重复；清理仅删已创建演示身份。'),['--file','demo-users.json'],p('Write demo-users.json as [{"identity":"demo_import_user","display_name":"Imported Demo"}]. This synthetic row has no password and cannot be used as a password-login credential until one is set.','demo-users.json 写 [{"identity":"demo_import_user","display_name":"Imported Demo"}]。此合成行无密码，设置前不可用于密码登录。'));
add('p-user assign-role','editor',p('PUTs a role name on an existing identity; omitting --role explicitly assigns null (unassigns), not leaves unchanged.','给已有 identity PUT 角色名；省略 --role 显式赋 null（取消分配），不是保留。'),p('stdout: assigned role -> <identity> (now role_id=<UUID-or->).','stdout: assigned role -> <identity> (now role_id=<UUID-or->)。'),p('Missing user/role fails. Save original role, verify list, restore that role to undo; unassigning does not clear the user’s own admin flag.','用户/角色不存在失败。保存原角色、list 核查、再赋原角色回退；取消分配不清用户自身 admin。'),['demo_user','--role','demo_role']);
for(const verb of ['activate','deactivate']) add(`p-user ${verb}`,'editor',p(`${verb === 'activate' ? 'Enables' : 'Disables'} an existing project end-user’s active flag. Not license activation, platform login or project membership.`,`${verb === 'activate' ? '启用' : '停用'}已有项目终端用户 active 标记。不是许可证激活/平台登录/项目成员。`),p(`stdout: <identity> is_active=${verb === 'activate'}.`,`stdout: <identity> is_active=${verb === 'activate'}。`),p(`Missing identity fails; verify p-user list. ${verb === 'activate' ? 'deactivate' : 'activate'} reverses the flag but cannot reverse past/in-flight business effects.`,`identity 不存在失败；p-user list 验证。${verb === 'activate' ? 'deactivate' : 'activate'} 可反转标记，不能撤销过去/进行中业务效果。`),['demo_user']);
add('p-user set-admin','editor',p('Sets the individual end-user’s is_admin using --admin true|false. Their assigned role can independently confer admin, so setting false alone is not full demotion if the role remains admin.','用 --admin true|false 设置用户自身 is_admin。所分配角色可独立授予 admin，故角色仍 admin 时仅设置 false 不等于完全降级。'),p('stdout: user <identity> admin=<bool>. Changes project-end-user administration, not platform privileges.','stdout: user <identity> admin=<bool>。改项目终端用户管理权限，不是平台权限。'),p('Missing identity/invalid boolean fails. Check both own flag and role; restore old boolean if needed and verify through public user data.','identity 不存在/布尔无效失败。检查自身标记与角色；需要时恢复旧布尔并查公开用户数据。'),['demo_user','--admin','false']);
add('p-user reset-mfa','editor',p('DELETEs the end-user’s second factor as operator recovery; does not reset the platform account’s MFA.','作为运维恢复 DELETE 终端用户二次验证，不重置平台账号 MFA。'),p('stdout reports cleared or had no two-factor authentication. The account may have to enroll again under project policy.','stdout 报告 cleared 或 had no two-factor authentication。项目策略可要求重新注册。'),p('Confirm the person’s identity out of band first. Missing user fails; this is not reversible by CLI. User enrolls a new factor and recovery codes; verify the next authorized login follows project policy.','先在带外确认身份。用户不存在失败；CLI 不可逆。用户需注册新验证器/恢复码，并验证下次授权登录遵循项目策略。'),['demo_user']);
add('p-user delete','editor',p('Deletes the project end-user identity; not a platform user or collaborator membership. Associated authorization/credential references can be affected.','删除项目终端用户身份，不是平台用户/协作者成员。可影响关联授权/凭据引用。'),p('stdout: deleted <identity>; success 0. Does not undo their earlier business-data writes.','stdout: deleted <identity>；成功 0。不撤销其先前业务写入。'),p('Inventory dependencies first and remove only disposable users. Verify p-user list; recreating an identity does not restore old UUID, MFA, keys or grants automatically.','先盘点依赖，仅删演示用户。p-user list 核查；重建同 identity 不自动恢复旧 UUID/MFA/key/授权。'),['demo_user']);
for(const family of ['role','authorizer']) for(const [key,n] of Object.entries(notes).filter(([k])=>k.startsWith(family+' '))) {
  const alias = 'user '+key;
  notes[alias] = {...n, argv:['viat',...alias.split(' '),...n.argv.slice(key.split(' ').length+1)], behavior:p('Exact dispatch alias of viat '+key+'. Despite the user prefix, it still uses the selected PROJECT and the same permissions. '+n.behavior[0], 'viat '+key+' 的完全分发别名。虽有 user 前缀，仍针对所选项目，权限相同。'+n.behavior[1])};
}
add('user ls','admin',p('GET /users lists the platform user directory, not project end users or project members. Requires platform Admin/Owner even without project selection.','GET /users 列平台用户目录，不是项目终端用户/项目成员。无需选项目但须平台 Admin/Owner。'),p('Text: email, platform role, display name; --json returns public rows/id/timestamps.','文本为 email/平台 role/显示名；--json 公开行/id/时间戳。'),p('Project Owner alone can receive 403. Ask platform Owner for access; no user changes, protect personal-data captures.','仅项目 Owner 也可 403。向平台 Owner 申请；不改用户，保护个人数据输出。'),['--json']);
add('user invite','login',p('Creates a new platform account. Without --project requires platform Admin/Owner; with --project AND --role requires Owner/Admin membership in that named project, not platform rank. Both flags must appear together. Does not send an email invitation: share generated credential out of band.','创建新平台账号。不带 --project 需平台 Admin/Owner；带 --project 和 --role 需该项目 Owner/Admin，而非平台级别。两个参数须同时。不会发送邀请邮件：生成凭据需带外交付。'),p('Text: invited email (UUID), optional one-time temp_password and project enrollment. --json contains user and generated temp_password when applicable. User-supplied password is not reprinted; minimum 8 characters.','文本含 invited email (UUID)、可选一次性 temp_password 与加入项目。--json 含 user 和适用时生成 temp_password。自设密码不再打印，至少 8 字符。'),p('Existing email/invalid role/missing pair fails. Protect output and transfer securely; verification via user ls (if allowed) and project member ls. Removing demo membership does not delete platform account; account cleanup is console/API work, no user delete CLI.','邮箱已存在/角色无效/缺配对失败。保护输出并安全交付；有权限时 user ls、project member ls 验证。移除演示成员不删平台账号；账号清理由控制台/API 完成，无 user delete CLI。'),['--email','teammate@example.invalid','--project','cli-demo','--role','developer']);
add('user set-role','owner',p('Sets PLATFORM owner/admin/developer/operator role by email. Normalizes role case; independent from project member set-role and project end-user role commands. Last platform Owner cannot be demoted.','按邮箱设置平台 owner/admin/developer/operator 角色，规范化大小写。独立于 project member set-role 和终端用户 role。不能降级最后平台 Owner。'),p('Text: <email> is now <role>; --json public account response. Takes effect on platform administration access.','文本: <email> is now <role>；--json 公开账号响应。影响平台管理访问。'),p('Promote another Owner before last-owner demotion. Record old role, verify user ls, restore original role to undo. Do not use platform elevation merely to fix project membership.','降级最后 Owner 前先提升另一个。记录旧角色、user ls 验证，恢复旧值回退。不要为修项目成员问题而提升平台权限。'),['teammate@example.invalid','operator']);
add('user reset-mfa','owner',p('Requires a platform login SESSION as well as platform Owner (PAT is refused). Clears target platform MFA and revokes its sessions, including sessions when no factor was present. Project p-user reset-mfa is separate.','除平台 Owner 外还需平台登录会话（PAT 拒绝）。清目标平台 MFA 并撤销会话，即使原来无验证器也撤销会话。项目 p-user reset-mfa 另算。'),p('Text says cleared/no factor and number of sessions signed out; --json preserves had_mfa/sessions_revoked.','文本为已清除/原无验证器和登出会话数；--json 保留 had_mfa/sessions_revoked。'),p('Verify the person out of band first. Cannot restore old factor/recovery codes: user must re-enroll in console and sign in again; operator policy may force enrollment.','先带外核实本人。不能恢复旧验证器/恢复码：用户须控制台重注册再登录；运维策略可强制注册。'),['teammate@example.invalid','--json']);
add('license show','login',p('GET /license reads deployment activation status without selecting a project; route remains accessible while deployment is unactivated.','GET /license 读取部署激活状态，不需项目；未激活时仍可访问。'),p('Text status/customer/expiry/activation/license ID when present, or NOT ACTIVATED; --json raw status. An unactivated status is successful read (exit 0).','文本为可用的 status/customer/expiry/activation/license ID 或 NOT ACTIVATED；--json 原状态。未激活也是读取成功（0）。'),p('A 403 license_required on other commands is not solved by project role changes. Obtain a valid code through your authorized supplier; no mutation/cleanup.','其他命令的 403 license_required 不能靠项目角色解决。通过授权供应方取得有效 code；无变更/清理。'),['--json']);
add('license activate','admin',p('POST /license/activate verifies a legitimate code against this official server image’s embedded verification key. CODE=- reads stdin and trims whitespace; no project needed. This is customer activation, not vendor key/code issuance.','POST /license/activate 以官方镜像内嵌验证 key 校验合法 code。CODE=- 从 stdin 读并去空白；不需项目。属于客户激活，不是厂商发 key/code。'),p('Text: activated. then license status; --json emits status. Accepted code updates deployment activation state.','文本: activated. 然后许可证状态；--json 输出状态。接受后更新部署激活。'),p('Empty/malformed/bad-signature/expired/incompatible codes fail. Do not invent or generate a vendor signing key. Obtain the correct valid code, verify license show afterward; no CLI deactivate/revoke exists. Never publish a real code.','空/格式错/签名错/过期/不兼容 code 失败。勿自创或生成厂商签名 key。获取正确 code，之后 license show 验证；无 CLI deactivate/revoke。勿公开真实 code。'),['-'],p('Supply an actually valid customer code via a protected stdin source only after explicit activation authorization. argv syntax can be checked without a code; this example is not an issued code or a runnable successful activation fixture.','仅在明确授权激活后，通过受保护 stdin 提供真实有效客户 code。可无 code 检查 argv 语法；此例不代表已签发 code 或可成功激活夹具。'));
add('logs query','member',p('Queries execution metadata for selected project; filters include endpoint UUID, request UUID, status range, UTC/RFC3339 time range and exact path. --before uses returned cursor. Does not query arbitrary business tables.','查询所选项目执行元数据；可按端点 UUID/请求 UUID/状态范围/UTC RFC3339 时间/精确路径筛。--before 用返回游标。不查任意业务表。'),p('Text rows include time/request/status/duration/path and next-page hint; --json returns paged response. Empty matches exit 0.','文本含时间/请求/状态/时长/路径及下一页提示；--json 分页响应。无匹配退出 0。'),p('Bad UUID/time/cursor/range fails. Use returned cursor unchanged and preserve filters while paging. Read-only; protect identity/payload-related metadata in captures.','UUID/时间/游标/范围无效失败。分页原样沿用游标和筛选。只读；保护输出中的身份/载荷相关元数据。'),['--limit','10','--json']);
add('logs search','member',p('Substring-searches log line content (minimum 3 characters); --stream optionally stdout/stderr/structured. Available only with PostgreSQL log backend, not all log sinks.','子串搜索日志内容（至少 3 字符）；--stream 可选 stdout/stderr/structured。仅 PostgreSQL 日志后端可用，不是所有 sink。'),p('Text: matching request/time/stream/content plus page cursor; --json returns search page. No matches exits 0.','文本含匹配请求/时间/stream/content 及游标；--json 搜索页。无匹配 0。'),p('Short query/unsupported backend/bad time fails. Narrow time range, paginate via --before; this does not search workflow outputs unless they were logged as lines. No mutation/cleanup.','短查询/后端不支持/时间错失败。缩小时间并 --before 分页；工作流输出只有作为日志行才可搜。无变更/清理。'),['demo','--limit','10','--json']);
add('logs show','member',p('Fetches one execution by request_id plus line logs; not the internal execution_log_id or endpoint UUID.','按 request_id 获取单执行和日志行，不是内部 execution_log_id/端点 UUID。'),p('Text: request/time/method/path/status/duration/error and lines; --json preserves full detail. No line logs is not proof execution did not run.','文本含请求/时间/方法/路径/状态/时长/错误及日志行；--json 完整详情。无日志行不证明没有执行。'),p('404: use request ID from query/run, correct project and retention window. Reads can expose sensitive logged business data; no execution/cleanup.','404 时核对 query/run 的请求 ID、项目及保留期。日志可含敏感业务数据；只读，不执行/清理。'),[ID,'--json']);
add('logs tail','member',p('SSE streams new project execution and line events, no initial backfill, excludes test runs. Other nodes appear when runs finish via ~2s DB polling; line output across nodes needs PostgreSQL log backend.','SSE 流新项目执行/日志事件，无初始回填，排除测试执行。其他节点完成后约 2 秒 DB 轮询出现；跨节点日志行需 PostgreSQL 后端。'),p('Text formats events; --json prints event data lines (not one JSON array). Reconnect notices/errors go to stderr; stops with error after five consecutive failures. Runs until interrupted otherwise.','文本格式化事件；--json 每行事件数据（不是一个 JSON 数组）。重连/错误写 stderr；连续五次失败后报错停止。否则持续到中断。'),p('Ctrl-C stops only the local reader (signal exit status is not the 0/1 command convention). No replay on reconnect: query/show gaps separately. This does not cancel running scripts and needs no remote cleanup.','Ctrl-C 仅停本地读取（信号退出码不属 0/1 命令约定）。重连不重放，缺口用 query/show 查。不取消脚本，无远程清理。'),['--json']);
add('audit query','member',p('Reads a PostgreSQL resource’s BUSINESS-DATA audit trail with resource credentials on the platform. Not control-plane /projects/:slug/audit. --record is record_id; --operator matches identity/user ID/email/kind.','用平台持有的资源凭据读 PostgreSQL 业务数据审计轨迹，不是控制面 /projects/:slug/audit。--record 是 record_id；--operator 匹配 identity/用户 ID/邮箱/kind。'),p('Text groups transactions and changed-field rows, then next-page --before; --json returns items/next_before/limit. Default server limit 100, clamped by deployment cap.','文本按事务分组变更字段行，并给 --before；--json 为 items/next_before/limit。服务端默认 100，受部署上限约束。'),p('Needs reachable PostgreSQL resource and installed/retained trail; a missing trail can be empty, not necessarily 404. Bad cursor/time or non-PostgreSQL fails. No writes/cleanup; output contains personal/business data.','需可达 PostgreSQL 及已安装/保留轨迹；无轨迹可为空，不必 404。游标/时间错或非 PostgreSQL 失败。无写入/清理；输出含个人/业务数据。'),['demo_db','--limit','10','--json']);
add('audit export','member',p('Exports every matching resource business-audit row as CSV; same filters as query except no page-size/before inputs. Contacts the resource DB through the server.','将所有匹配资源业务审计导出 CSV；除无分页大小/before 外与 query 同筛选。通过服务端访问资源 DB。'),p('UTF-8 BOM CSV on stdout, or --out writes a local file and stderr reports path/row count. Not JSON; large exports can be substantial.','stdout 为 UTF-8 BOM CSV；--out 写本地文件，stderr 报路径/行数。不是 JSON；大导出可能很大。'),p('Invalid resource/filter/DB connectivity or local file write fails. Narrow time/table filters and securely store or delete demo-audit.csv; export does not remove server trail rows.','资源/筛选/DB 连接/文件写入错误会失败。缩小时间/表筛选，安全保存或删除 demo-audit.csv；导出不删服务端轨迹。'),['demo_db','--out','demo-audit.csv']);
add('files list','member',p('Lists managed-file metadata from a storage resource, with optional owner/prefix filters and cursor. Console membership authorizes read; data-plane file authz rules are a separate boundary.','从 storage 资源列受管文件元数据，可按 owner/prefix/游标筛。控制台成员授权读取；数据面 file authz 是另一边界。'),p('Text: UUID, size, owner, uploaded, key plus next cursor; --json response includes page metadata. Default server page size is applied when --limit is absent.','文本为 UUID/大小/owner/上传/key 和下一游标；--json 含分页元数据。无 --limit 用服务端默认页大小。'),p('Requires configured metadata PostgreSQL and byte backend; bad storage/folder/cursor fails. Copy actual UUID for get/rm. No file bytes changed; protect output.','需配置元数据 PostgreSQL 和字节后端；storage/folder/游标错误失败。get/rm 复制真实 UUID。不改字节；保护输出。'),['demo_storage','--limit','10','--json']);
add('files get','member',p('Fetches metadata first. --info prints row JSON only; otherwise downloads bytes. Default local destination is a sanitized basename from stored name; --out - writes raw stdout. --info does not mean download.','先读元数据。--info 仅打印行 JSON；否则下载字节。默认目标为清理后的存储名称 basename；--out - 写原始 stdout。--info 不下载。'),p('Download stdout is raw bytes only when --out -; file mode writes path/size notice on stderr. It can overwrite the chosen local file. --info emits pretty JSON on stdout.','仅 --out - 下载时 stdout 为原字节；文件模式 stderr 报路径/大小。可覆盖指定本地文件。--info 在 stdout 格式化 JSON。'),p('Missing/deleted file or unavailable byte store fails. Use --info first and explicit safe --out to avoid accidental overwrite; check bytes/content type, delete disposable download locally. No remote mutation.','文件不存在/已删或字节后端不可用失败。先 --info，再显式安全 --out 避免误覆盖；检查字节/类型，本地删除演示下载。无远程变更。'),['demo_storage',ID,'--info']);
add('files put','editor',p('Reads a local file and uploads as console account; optional key/name/content-type/owner/reason. Default key is generated id/name; key collision is refused, not replace. No script receives storage credentials.','读本地文件以控制台账号上传；可带 key/name/content-type/owner/reason。默认 key 为生成 id/name；key 冲突拒绝，不替换。脚本不获得 storage 凭据。'),p('Text gives new UUID/key/size; --json metadata row. Writes byte store plus metadata/audit; real storage effects occur immediately.','文本含新 UUID/key/大小；--json 元数据行。写字节后端及元数据/审计；真实存储立即生效。'),p('409 file_exists, 413 file_too_large, 415 file_type_not_allowed or required audit reason can fail. Verify files get --info with returned UUID. Cleanup files rm with required reason; do not merely delete your local source.','409 file_exists/413 file_too_large/415 file_type_not_allowed 或缺审计 reason 可失败。以返回 UUID 执行 files get --info 验证。清理用 files rm 并给需要 reason；仅删本地源文件不够。'),['demo_storage','demo.txt','--reason','synthetic demo upload','--json'],p('Existing isolated storage resource demo_storage, including its metadata PostgreSQL and local/S3 byte backend, plus demo.txt containing synthetic text. This cannot succeed without actual provisioned storage.','已有隔离 demo_storage，包括元数据 PostgreSQL 和 local/S3 字节后端；demo.txt 为合成文本。无真实配置存储不能成功。'));
add('files rm','editor',p('Soft-deletes metadata (row remains marked deleted) and deletes bytes, as console identity. --reason is required if metadata audit policy requires it.','以控制台身份软删元数据（行保留删除标记）并删除字节。元数据审计策略要求时必须 --reason。'),p('stdout: deleted <UUID>. Not a reversible move to trash and not deletion of the local upload source.','stdout: deleted <UUID>。不是可恢复回收站，也不删本地上传源。'),p('Bad UUID/missing file/reason/backend failure can fail. Verify list excludes it; retain source/backups before deletion. Re-upload is a new file identity and does not undelete old row/restore grants automatically.','UUID 错/文件不存在/缺 reason/后端失败可报错。list 确认不再列出；删除前保留源/备份。重传是新文件身份，不自动恢复旧行/授权。'),['demo_storage',ID,'--reason','remove synthetic demo']);
add('script delete','editor',p('Deletes a saved script draft; does not undo earlier executions or business-resource writes. Published dependency handling is separate from deleting the draft.','删除保存脚本草稿，不撤销先前执行或业务资源写入。发布依赖处理与草稿删除是不同操作。'),p('stdout: deleted <name>; 0 after successful DELETE.','stdout: deleted <name>；DELETE 成功后 0。'),p('Inventory endpoint/workflow/schedule dependencies and save source first. Verify list and publish plan; recreate from saved source if needed. Do not assume deletion is a safe way to withdraw one published route: use endpoint unpublish for that.','先盘点端点/工作流/调度依赖并保存源码。list 和 publish plan 验证；需要时从保存源码重建。勿以删草稿安全撤下某路由：应使用 endpoint unpublish。'),['demo_echo']);
add('push','editor',p('CWD repo → remote drafts. --only chooses kinds, not filenames; empty means all, unknown kinds silently do nothing. Mirror deletion is ALREADY ON for meta, schedules, watches, queue/ws triggers, syncable chat accounts/triggers and endpoint nodes; scripts/workflows/resources are never pruned by absence. No --prune flag exists on push.','CWD 仓库 → 远程草稿。--only 选类别而非文件，空表示全部，未知类别静默无操作。meta/调度/watch/queue/ws trigger/可同步聊天账号及 trigger/端点已默认镜像删除；脚本/工作流/资源不因缺本地文件而删。push 没有 --prune 参数。'),p('Prints per-stage writes/deletions, pending-publish and excluded-drift summaries; --json appends {"ok":true} but stage/hint text can still precede it (not a clean single JSON stream). No DDL or publish. Changes apply stage-by-stage, not one global transaction.','打印各阶段写入/删除、待发布与未推差异摘要；--json 最后追加 {"ok":true}，前面仍可有阶段/提示文本（不是纯单 JSON）。不运行 DDL/发布。逐阶段生效，不是全局事务。'),p('Full metadata/settings changes can require project Owner/Admin; content-only stages need editor and some operational stages only membership. Refuses stale authz model before meta writes unless --force-authz; model/role deletions need --yes. These overrides are different and are not a general destructive-sync confirmation. Run diff and keep a complete backup before push; partial failure leaves prior stages applied. Pull/reconcile drafts, migrate DB explicitly, then publish intentionally.','完整元数据/设置变更可需项目 Owner/Admin；纯内容阶段需 editor，部分运行阶段仅需成员。meta 写前 authz 版本过期则拒绝，--force-authz 才越过；模型/角色删除需 --yes。两个覆盖不同，不是整个破坏性同步确认。先 diff 并完整备份；部分失败保留已完成阶段。pull/核对草稿、显式迁移 DB，再有意发布。'),['--only','scripts,workflows'],p('Run from the COMPLETE intended repo root with matching viat.yaml project.slug and selected project; session discovery does not find the repo root for you. Supported kinds: meta,resources,scripts,workflows,schedules,watches,queue_triggers,ws_triggers,chat,endpoints,crate. Built-in auth endpoints/roles and legacy system resource are skipped.','在完整目标仓库根运行，viat.yaml project.slug 须匹配所选项目；会话发现不替你定位仓库根。类别：meta,resources,scripts,workflows,schedules,watches,queue_triggers,ws_triggers,chat,endpoints,crate。跳过内建 auth 端点/角色及旧 system 资源。'));
add('pull','member',p('Remote drafts → CWD files, not published snapshots. --only kinds match push, unknown kinds silently ignored. Writes/overwrites represented files; it is not a universal local-prune/reset operation (e.g. server-removed scripts can leave local files). Secret fields are $secret placeholders; existing top-level plain $keep markers are preserved when applicable.','远程草稿 → CWD 文件，不是发布快照。--only 类别同 push，未知类别静默忽略。写/覆盖所代表文件；不是通用本地 prune/reset（如远程已删脚本可仍留本地）。秘密字段写 $secret 占位；适用时保留已有顶层 plain $keep。'),p('Prints pulled items; --json appends {"ok":true}, not guaranteed to suppress stage text. Updates local authz model-version record. No remote content mutation besides ordinary login refresh.','打印已 pull 项；--json 最后附 {"ok":true}，不保证抑制阶段文本。更新本地 authz 模型版本记录。除常规登录刷新外不改远程内容。'),p('Full pull/export includes editor-gated role/authorizer/tree/model reads; a member can pull only permitted content stages. Back up uncommitted files first; failures can leave partial local output. Inspect diff and local stale files before pushing; do not push an incomplete checkout.','完整 pull/export 包含需 editor 的角色/认证器/tree/模型读取；成员只能拉有权限阶段。先备份未提交文件；失败可留下部分本地输出。push 前检查 diff 和旧文件；勿推不完整仓库。'),['--only','scripts,workflows'],p('CWD must be the intended repo root, and selected project must match. Pull skips managed auth nodes/roles and non-rebuildable row-secret/QR chat accounts (with notice); their absence is not permission to delete them.','CWD 须为目标仓库根、项目须匹配。跳过托管 auth 节点/角色及无法重建的行秘密/扫码聊天账号（会提示）；缺失不表示可删除。'));
add('export','member',p('Freshly pulls selected/positional project into temporary staging, packs gzip tar .viatpkg, cleans staging. Runtime output default ./<slug>.viatpkg. Same --only kind selection and permissions as pull. Does not export credentials or select a different project.','把所选/位置参数项目新 pull 到临时目录，打成 gzip tar .viatpkg 后清临时目录。输出默认 ./<slug>.viatpkg。--only 类别与权限同 pull。不导出凭据、不切项目。'),p('Prints pull progress then exported project <slug> -> <path>; output file can overwrite an existing file. Not a server-wide backup or an upstream database/file-byte backup.','打印 pull 进度，再 exported project <slug> -> <path>；可覆盖已有输出文件。不是整服务端备份，也不备上游 DB/文件字节。'),p('Full export needs editor-gated reads; bad destination/file access can fail after pulling. Keep bundle private because plain/source/config still travel. Remove demo.viatpkg when finished; restore missing credentials separately on import.','完整导出需 editor 读取；目标/文件权限错可在 pull 后失败。bundle 含 plain/源码/config，须保密。用完删除 demo.viatpkg；导入时秘密另行恢复。'),['cli-demo','--output','demo.viatpkg']);
add('import','login',p('Unpacks .viatpkg into temporary staging, reads viat.yaml, creates target project if absent, applies non-destructive upserts by default. --as changes target slug; current selection is not the destination override. --prune deliberately mirrors server-only items away. New secret-bearing resources are skipped; existing ones are entirely kept unless --update-resources, to avoid pointing target credentials at source hosts.','解包 .viatpkg 到临时目录，读 viat.yaml，必要时创建目标项目；默认非破坏 upsert。--as 改目标 slug；当前选择不是目标覆盖。--prune 明确启用镜像删除。新含秘密资源被跳过；已有含秘密资源整体保留，除非 --update-resources，防止目标凭据连源主机。'),p('Prints imported project, pending publish, skipped-secret and kept-resource summaries; skipped/kept resources do not by themselves fail the command. No publish or DB migration. Does not change selected project.','打印 imported project、待发布、缺秘密跳过/保留资源摘要；跳过/保留本身不导致失败。不发布/迁移，不改变当前项目。'),p('Existing target stages require their normal membership/editor/Owner-Admin settings permissions. Invalid archive/missing viat.yaml/stage errors exit 1 after any earlier remote writes; no batch rollback. Back up target first, inspect skipped resources, select destination explicitly for verification, provision credentials safely, diff then publish. Remove local demo bundle/staging leftovers only after inspection.','已有目标各阶段需正常成员/editor/Owner-Admin 设置权限。包无效/缺 viat.yaml/阶段错误退出 1，已写阶段保留，无批回滚。先备份目标，检查跳过资源、显式选目标核查、安全提供秘密、diff 后发布。检查后才删本地演示包/残留临时目录。'),['demo.viatpkg','--as','cli-demo-copy']);
add('db status','editor',p('Discovers CWD migrations/<folder/resource>/*.sql and compares each file’s checksum with the resource DB ledger. Resource omitted means all discovered resources. Supports PostgreSQL/MySQL/SQLite, not platform migrations or SQL Server. No migrations directory is an early successful no-op even without login.','发现 CWD migrations/<folder/resource>/*.sql 并将文件 checksum 与资源 DB ledger 比。省略 resource 表示全部发现资源。支持 PostgreSQL/MySQL/SQLite，不是平台迁移/SQL Server。无迁移目录时即使未登录也早期成功无操作。'),p('Text: applied/baseline/pending/CHANGED/FAILED and ledger-only rows. Changed/failed rows are reported, not themselves a nonzero status command result.','文本为 applied/baseline/pending/CHANGED/FAILED 及仅 ledger 行。报告 changed/failed 本身不使 status 非零。'),p('Needs readable SQL files and reachable existing resource DB. Ledger reads never create the ledger table; a database with no prior migration returns an empty ledger. Restore changed applied files; add a new corrective migration, never edit applied history. No destructive cleanup is automatic.','需可读 SQL 与可达资源 DB。ledger 读取不会创建 ledger 表；从未迁移的数据库返回空 ledger。恢复被改已应用文件，以新迁移纠正，勿改已应用历史。无自动破坏性清理。'),['demo_db']);
add('db migrate','publisher',p('Applies pending SQL files in lexical ID order, stopping on first error. Refuses changed applied files, any failed ledger row, or out-of-order files unless --allow-out-of-order. --dry-run reads/plans only (editor suffices); absent resource means all discovered directories. No directory returns successful no-op before login.','按字典 ID 顺序执行待迁移 SQL，首错停止。拒绝被改已应用文件、失败 ledger 行和乱序文件（除非 --allow-out-of-order）。--dry-run 只读/计划（editor 足够）；省略资源则所有发现目录。无目录会在登录前成功无操作。'),p('Text: would apply/up to date/applied with duration/already applied. Actual changes run with held resource credentials. PostgreSQL/SQLite pair each file and ledger transaction; MySQL DDL auto-commits and can leave partial state/failed row.','文本为 would apply/up to date/applied（时长）/already applied。真实变更使用平台资源凭据。PostgreSQL/SQLite 文件和 ledger 同事务；MySQL DDL 自动提交，可留部分状态/失败行。'),p('Use only isolated authorized DBs for examples. Timeout/connection loss may leave SQL running: inspect status before retry. Dry-run ledger reads do not initialize ledger tables. Back up first; rollback is a NEW reviewed migration/manual DB repair, not a CLI down command. Push never runs this for you.','示例仅用已授权隔离 DB。超时/断连可仍在执行 SQL，重试前查 status。dry-run 读取 ledger 不初始化表。先备份；回退需新审核迁移/手工修库，无 CLI down。push 不代跑。'),['demo_db','--dry-run']);
add('db baseline','publisher',p('Marks every local file through required --through ID as already applied without running SQL. For an existing schema that exactly matches those files; not a way to hide drift. Requires writable supported resource DB and matching local files.','将本地至必填 --through ID 的所有文件标已应用，不跑 SQL。仅用于已精确具备这些 schema 的库，不是隐藏漂移。需可写受支持资源 DB 和匹配文件。'),p('Text reports baselined count/resource; writes ledger and stored checksums, not business DDL.','文本报告 baseline 数量/资源；写 ledger/checksum，不跑业务 DDL。'),p('Missing through file/refused ledger conflict fails. Verify schema separately BEFORE baseline, then db status. Wrong baseline requires deliberate DB ledger recovery with backups; no unbaseline CLI.','through 文件缺失/ledger 冲突拒绝失败。baseline 前独立验证 schema，再 db status。错误 baseline 需备份支持下有意修 ledger；无 unbaseline CLI。'),['demo_db','--through','0001_demo']);
add('db repair','publisher',p('After MANUAL repair of a partially applied MySQL file, clears only its failed ledger row so next migrate can rerun the entire file. Never clears an applied row; not an automatic SQL repair.','手工修复部分应用 MySQL 文件后，只清其失败 ledger 行，使下次 migrate 整文件重跑。绝不清已应用行，不自动修 SQL。'),p('Text: cleared the failed row ... or server result; changes ledger state only.','文本为 cleared the failed row ... 或服务端结果；只变 ledger 状态。'),p('Confirm actual DB state and idempotency before clearing, else re-run can duplicate DDL/data. Missing/nonfailed row may refuse/no-op per response; verify db status, retain diagnostics/backups and apply corrected recovery deliberately.','清除前确认真实 DB 和幂等性，否则重跑可重复 DDL/数据。不存在/非失败行可拒绝或按响应无操作；db status 验证、保留诊断/备份并有意恢复。'),['demo_db','0001_demo']);
add('authz rule list','editor',p('Reads server authorization rules; optional --origin must be platform/delegated and --type filters a model type. Not project roles or endpoint authentication settings.','读服务端授权规则；--origin 可选 platform/delegated，--type 筛模型类型。不是项目角色/端点认证设置。'),p('Text: rule ID, origin, effect, type.action and expression; --json emits filtered rule array. No matches is successful.','文本为规则 ID/origin/effect/type.action/表达式；--json 筛后规则数组。无匹配成功。'),p('Invalid origin fails locally. Use IDs here for handover; no policy mutation/cleanup. A read’s model version is not a guarantee for a later push.','origin 无效在本地失败。用此 ID 交接；不改策略，无需清理。读取版本不保证之后 push 不变。'),['--origin','platform','--json']);
add('authz rule set-origin','editor',p('Choose explicit rule IDs OR --not-in-file, never both/neither. --not-in-file requires CWD viat.yaml with authz section and --origin delegated; selects platform rules absent by content. --dry-run lists changes. Real run PUTs rules one by one; already-matching rows skipped.','选择显式规则 ID 或 --not-in-file，不能同时/都不选。--not-in-file 需 CWD viat.yaml 有 authz 并 --origin delegated；按内容选文件未声明 platform 规则。--dry-run 列变更。实际逐规则 PUT，同 origin 跳过。'),p('Text lists would-set/set/nothing-to-change. Failure reports previously changed rows and remainder; partial writes persist. A current checkout’s recorded model version is advanced after successful handover; stale checkouts stay stale.','文本为 would-set/set/nothing-to-change。失败报告已改和剩余；部分写保留。成功交接后仅原本当前 checkout 的模型版本记录前进，过期 checkout 仍过期。'),p('Inspect dry-run before handing ownership away: future push mirrors only platform-owned rules. To undo, explicitly set the same IDs back to previous origin. After partial failure list/reconcile, then rerun remaining work; no all-rules transaction.','移交前检查预览：未来 push 仅镜像 platform 规则。回退需把同 ID 显式设回旧 origin。部分失败后 list/核对再续；无全规则事务。'),[ID,'--origin','delegated','--dry-run']);
add('call','login',p('Default calls {server}/p/{selected-project}{path} with optional project_token, NOT access_token; absent token may still call public routes. Plain mode bypasses proxies and supports GET/POST/PUT/PATCH/DELETE only. --console instead calls an absolute console path with login refresh/proxy settings and that route’s own permission check; selected project not needed for console mode. --body is sent as JSON content-type string, not validated JSON.','默认请求 {server}/p/{selected-project}{path}，用可选 project_token 而非 access_token；无 token 仍可访问公开路由。普通模式绕过代理，仅 GET/POST/PUT/PATCH/DELETE。--console 改为绝对控制台路径，使用登录刷新/代理设置及该路由权限；无需所选项目。--body 作为 JSON content-type 字符串发送，不校验 JSON。'),p('stdout: HTTP status line then raw body. Non-2xx prints these first then exits 1. Valid HTTP error responses are not parsed as successful business results. Streaming is not a live event renderer: response text is collected.','stdout 先 HTTP 状态行、再原始 body。非 2xx 先打印再退出 1。不把有效 HTTP 错误当成功业务结果。流不是实时事件渲染：收集响应文本。'),p('This can mutate ANY allowed route; inspect method/path/body before opt-in. Login does not mint project_token automatically. For 401 distinguish console session from runtime authorizers; do not copy a PAT into public examples. Verify effects via route-specific reads and reverse them explicitly; no generic undo/retry safety.','可修改任意有权限路由；授权前检查 method/path/body。平台登录不自动签 project_token。401 需区分控制台会话与运行时认证器；勿把 PAT 放公开示例。以相应读取验证并显式回退，无通用撤销/重试安全。'),['--console','/auth/whoami']);
add('mcp','login',p('Starts stdio JSON-RPC server, not a one-shot tool invocation. VIAT_SERVER/VIAT_TOKEN/VIAT_PROJECT override discovered config. Server URL and token strings required at startup; project can be provided by individual tool. Credentials are validated at tool-call time. Client always bypasses HTTP proxies; do not assume CLI refresh-on-401 applies to this separate MCP client.','启动 stdio JSON-RPC 服务，不是单次工具调用。VIAT_SERVER/VIAT_TOKEN/VIAT_PROJECT 覆盖发现配置。启动需 URL/token 字符串；项目可逐工具提供。凭据在调用时验证。此客户端始终绕过 HTTP 代理；不要假定普通 CLI 的 401 刷新也适用。'),p('stdout contains protocol frames only; diagnostics on stderr. Lives until client/stdio closes; startup config/protocol errors return nonzero. A running process or successful tools/list does not prove server activation/access.','stdout 只协议帧，诊断写 stderr。持续到客户端/stdio 关闭；配置/协议启动错误非零。进程运行或 tools/list 成功不证明服务端已激活/有访问权。'),p('Launch from an MCP host with controlled config/PAT scope; later write/trigger/call tools can cause real effects under the token owner’s project roles. Stop the host process to end transport, revoke disposable PAT separately; stopping does not revoke credentials or undo tool calls.','由 MCP host 用受控配置/PAT 范围启动；之后 write/trigger/call 工具按 token 所有人项目角色产生真实效果。停止 host 只停传输，演示 PAT 须另撤销；停止不撤凭据、不撤销调用。'),[]);


add('resource list','member',p('Lists all resource folders in the selected project. Does not connect to upstream services.','列所选项目所有文件夹资源，不连接上游。'),p('Text: qualified path, kind and plain JSON; --json emits public rows (secret summaries, never secret values).','文本为限定路径、kind 和 plain JSON；--json 输出公开行（秘密摘要而非秘密值）。'),p('Plain may contain sensitive non-secret settings: handle captured output carefully. Verify names here before edits; no cleanup.','plain 可能包含敏感非秘密设置：谨慎保存输出。编辑前在此核对名称；无需清理。'),['--json']);
add('resource show','member',p('Resolves a folder-qualified resource, then reads public data only.','解析带文件夹的资源名，只读公开数据。'),p('Text: name (kind) and pretty plain; --json also exposes public metadata/secret mask, not credentials.','文本为 name (kind) 与格式化 plain；--json 还含公开元数据/秘密掩码，不含凭据。'),p('Missing/ambiguous reference fails: copy the qualified name from resource list. A *** mask is not a value to feed edit. No mutation or cleanup.','引用缺失/歧义会失败：从 resource list 复制限定名。*** 掩码不能作为 edit 的值。无变更，无需清理。'),['demo_config','--json']);
add('resource create','editor',p('Reads --file as YAML/JSON and POSTs the resulting object: name, optional folder, kind, complete plain and secret. No repo placeholder stripping here. Config example needs plain.data, not a top-level data key.','把 --file 读为 YAML/JSON 后 POST 对象：name、可选 folder、kind、完整 plain 和 secret。这里不去除仓库占位符。config 例需 plain.data，而非顶层 data。'),p('stdout: created <name>; 0 after save. Kind validation and, for PostgreSQL audit configuration, DDL installation can occur on save.','stdout: created <name>；保存后退出 0。保存可执行 kind 验证，以及 PostgreSQL audit 配置的 DDL 安装。'),p('Malformed YAML, reserved system name, duplicate identity or missing kind-specific credentials fails. Verify resource show; delete demo_config when unused. Do not expect a failed later step to undo an upstream schema change.','YAML 错误、保留名 system、重复身份或缺类型凭据会失败。用 resource show 验证；不用时删 demo_config。勿假定后续失败会撤销上游 schema 变更。'),['--file','demo-resource.yaml'],p('Create demo-resource.yaml with {"name":"demo_config","kind":"config","plain":{"data":{"enabled":true}},"secret":{}}. JSON is valid YAML; this fixture needs no provider.','将 demo-resource.yaml 写为 {"name":"demo_config","kind":"config","plain":{"data":{"enabled":true}},"secret":{}}。JSON 是有效 YAML；此夹具无需提供方。'));
add('resource edit','editor',p('Full PUT replacement, not a merge: supply kind, complete plain and all secrets that must remain. Direct YAML is not the pull/push placeholder format.','完整 PUT 替换而非合并：需 kind、完整 plain 和所有要保留秘密。直接 YAML 不等于 pull/push 占位格式。'),p('stdout: updated <name>; immediate resource changes can affect runtime calls without endpoint publish.','stdout: updated <name>；资源立即改变，可在未发布端点时影响运行时调用。'),p('Never reconstruct secrets from show masks. For one-field rotation use set-secret; for plain use set-field. Back up original full settings securely before replace, then show/test as appropriate; restore with a complete trusted file.','不可用 show 掩码重建秘密。单字段轮换用 set-secret，plain 用 set-field。替换前安全备份完整设置，再按需 show/test；用可信完整文件恢复。'),['demo_config','--file','demo-resource.yaml']);
add('resource set-secret','editor',p('GETs the existing kind, validates field against its declared secret names, then reads stdin. Refuses terminal input, empty input and unknown fields; strips trailing CR/LF. PATCH overlays only this secret field.','先 GET kind，按声明秘密字段名校验，再读 stdin。拒绝终端输入、空输入和未知字段；去除末尾 CR/LF。PATCH 只覆盖该秘密字段。'),p('stdout: set <name>.<field>; never echoes the secret or length. Existing unrelated fields remain.','stdout: set <name>.<field>；不回显秘密或长度，其他字段保留。'),p('Use a protected file or printf pipe, not argv. It cannot create a missing resource. Verify with a deliberately authorized connectivity check; old secret is not recoverable, so retain a secure rollback credential until rotation is confirmed.','使用受保护文件或 printf 管道，不放 argv。不能创建不存在资源。经明确授权后连通性检查；旧秘密不可读回，确认轮换前须安全保留回退凭据。'),['demo_secret','value'],p('An existing secret-kind resource demo_secret. Example shell: printf %s demo-only | viat resource set-secret demo_secret value. The argv manifest stores only the CLI tokens; stdin is separate.','已有 secret 类型 demo_secret。shell 示例：printf %s demo-only | viat resource set-secret demo_secret value。argv 清单仅存 CLI token，stdin 另供。'));
add('resource set-field','editor',p('Requires exactly one of --value or --file at runtime. Default stores a string; --json parses JSON (it is NOT output-format mode). Reads plain, changes one key, PATCHes the whole plain object, then checks returned field presence. --json --value null removes a set optional field.','运行时 --value/--file 必选其一。默认存字符串；--json 解析 JSON（不是输出格式）。读取 plain，改一键，将完整 plain PATCH，再检查返回字段存在。--json --value null 移除已设置可选字段。'),p('stdout: set or removed <name>.<field>. Unknown/dropped fields fail after the write attempt; normalization may change the value. Removing PostgreSQL audit drops triggers but retains its trail table.','stdout: set 或 removed <name>.<field>。未知/被丢弃字段在尝试写入后失败；规范化可改变值。删除 PostgreSQL audit 会删触发器但保留轨迹表。'),p('Use resource show to inspect before/after and preserve the old field for rollback; concurrent edits can be overwritten because plain is read-modify-write. Wrong JSON/type fails; do not retry on the assumption that no write happened.','用 resource show 检查前后并保存旧字段回退；plain 是读改写，可覆盖并发编辑。JSON/类型错误会失败；不可假定未写入而盲重试。'),['demo_config','data','--json','--value','{"enabled":false}']);
add('resource test','editor',p('Calls the platform’s kind-specific connectivity/key probe; can contact real providers. http_api GETs base_url with its credentials: transport errors/5xx fail, but 401/404/405 can pass (reachability, not authorization). Database/broker/mail/cloud handshakes authenticate; crypto_key tests local cryptography.','调用平台按类型提供的连接/密钥探测，可能访问真实提供方。http_api 携凭据 GET base_url：传输错误/5xx 失败，401/404/405 可成功（可达不等于已授权）。数据库/消息/邮件/云握手会认证；crypto_key 测本地密码学。'),p('stdout ok or fail: <error>; false ok exits 1. Passing schema warnings go to stderr and leave exit 0; invalid authz_tables bindings can fail.','stdout 为 ok 或 fail: <error>；ok=false 退出 1。成功附 schema 警告写 stderr，仍 0；无效 authz_tables 绑定可失败。'),p('Do not run without upstream opt-in. Check credentials/schema and warnings, not just exit 0. No provider rollback is promised; this is not a script run or a notification delivery guarantee.','未经上游授权勿运行。检查凭据/schema 及警告，不只看退出 0。不承诺提供方回退；不是脚本执行，也不保证通知到达。'),['demo_config']);
add('resource refresh','editor',p('POST /schema/refresh invalidates schema caches across instances for reread on next use; no migration/DDL is run.','POST /schema/refresh 跨实例使 schema 缓存失效，下次使用重读；不运行迁移/DDL。'),p('stdout: refreshed <name>: every instance re-reads the schema on its next use.','stdout: refreshed <name>: every instance re-reads the schema on its next use。'),p('After DDL, also republish CRUD endpoints whose resolved columns were frozen. Unsupported kind/missing resource fails; use show first. Cache invalidation needs no undo and cannot repair schema itself.','DDL 后还需重新发布冻结列的 CRUD 端点。不支持类型/资源不存在会失败；先 show。缓存失效无需撤销，也不能修复 schema 本身。'),['demo_db']);
add('resource delete','editor',p('DELETEs the resource definition; does not mean delete its upstream database/bucket. Runtime consumers can break immediately.','删除资源定义，不表示删除上游数据库/桶。运行时消费者可立即失效。'),p('stdout: deleted <name>; 0 after successful DELETE.','stdout: deleted <name>；DELETE 成功后 0。'),p('409 resource_in_use names endpoint bindings to rebind/delete first. Inventory scripts and saved configuration, then remove only a disposable resource; recreation needs original credentials, which show/pull never recover.','409 resource_in_use 会列出需先重绑/删除的端点。盘点脚本并保存配置，只删可丢弃资源；重建需要原凭据，show/pull 无法恢复。'),['demo_config']);

add('script list','member',p('Lists current draft scripts across folders, not published snapshots.','列所有文件夹当前草稿脚本，不是发布快照。'),p('Text: qualified path, language, v<version>; --json emits public script list. Empty list succeeds.','文本为限定路径、语言、v<version>；--json 输出公开脚本列表。空列表成功。'),p('Use qualified names to avoid ambiguity. Read-only; no cleanup.','使用限定名避免歧义。只读，无需清理。'),['--json']);
add('script create','editor',p('Reads UTF-8 --file and creates a draft. --name may be folder/name; --language is validated server-side. new is an alias. Creation does not publish or execute.','读取 UTF-8 --file 创建草稿。--name 可为 folder/name；--language 在服务端校验。别名 new。不发布、不执行。'),p('stdout: created <name> (v<version>).','stdout: created <name> (v<version>)。'),p('Missing file/invalid language/duplicate name fails. Verify script show; delete the demo script after removing dependent fixtures/endpoints.','文件缺失/语言无效/重名会失败。script show 验证；移除依赖夹具/端点后可删演示脚本。'),['--name','demo_echo','--language','python','--file','demo.py'],p('Write demo.py containing def main(): return {"ok": True} (put return on an indented line). No resources are used; server needs Python/uv to execute it later.','demo.py 写 def main(): return {"ok": True}（return 放在下一缩进行）。不使用资源；之后执行需服务端 Python/uv。'));
add('script show','member',p('Reads saved draft source, including its version and dedicated-worker settings.','读已保存草稿源码、版本和 dedicated worker 设置。'),p('Text includes # name (language, vN), content, dedicated and dedicated_count; --json returns full public object.','文本含 # name (language, vN)、content、dedicated 与 dedicated_count；--json 返回完整公开对象。'),p('404/ambiguous name: select the right project and qualify folder. Source may contain accidental hard-coded secrets; protect captures. No mutation/cleanup.','404/歧义：核对项目并限定文件夹。源码可能意外硬编码秘密；保护输出。无变更/清理。'),['demo_echo','--json']);
add('script update','editor',p('Partial PATCH; requires at least one of --file/--dedicated/--no-dedicated/--dedicated-count before loading config. edit aliases update. Only supplied fields change; saved draft advances, not published snapshot.','部分 PATCH；加载配置前要求至少 --file/--dedicated/--no-dedicated/--dedicated-count 之一。edit 是别名。只改传入字段；变更草稿，不改已发布快照。'),p('stdout: updated <name> → vN plus pending-endpoint hint when present.','stdout: updated <name> → vN，可附待发布端点提示。'),p('Conflicting dedicated flags/invalid count/file fail. Save old source/settings, verify show, then intentionally publish; restore saved draft and republish to undo a shipped change.','dedicated 冲突/数量或文件无效会失败。保存旧源码/设置，show 核查后有意发布；恢复旧草稿并重新发布可回退已交付变更。'),['demo_echo','--file','demo.py']);
add('script run','editor',p('Runs the live draft with JSON --args (runtime default {}). --input is an alias. Real resource calls and writes can occur; not offline. --record writes returned http/graphql/cloud cassettes after success.','以 JSON --args（运行时默认 {}）执行在线草稿。别名 --input。可发生真实资源调用/写入，并非离线。--record 成功后写回 http/graphql/cloud cassette。'),p('Success prints pretty output on stdout and captured stderr on stderr; ok=false prints error and exits 1. Explicit ViatResponse/stream results have output=None: successful CLI output can be null, not an HTTP failure. Shell stdout is logs, not the result. The draft API does not return the full HTTP response envelope.','成功 stdout 格式化 output，捕获 stderr 写 stderr；ok=false 打印错误并退出 1。显式 ViatResponse/流的 output=None：成功 CLI 输出可为 null，不代表 HTTP 失败。Shell stdout 是日志，不是结果。草稿 API 不返回完整 HTTP 响应信封。'),p('Review external side effects before running. Confirm request via logs; use a published/scratch endpoint to verify HTTP status/headers. Cassettes omit request credentials but can retain sensitive response bodies: review/delete generated files; CLI cannot undo external writes.','运行前审查外部副作用。用 logs 核查请求；HTTP 状态/头须用发布/隔离端点验证。Cassette 不存请求凭据但可含敏感响应体：审查/删除生成文件；CLI 不能撤销外部写入。'),['demo_echo','--args','{}']);
add('script logs','member',p('Resolves script first, then merges one page of endpoint-dispatch executions and draft test runs, newest first. Workflow-step executions belong to the workflow and are absent here.','先解析脚本，再合并一页端点执行与一页草稿测试，按新到旧。工作流步骤执行归属工作流，此处没有。'),p('stdout pretty {items:[...]}, or a no-executions explanation; stderr warns when either source reaches 50 rows. No --json flag: nonempty output is already JSON.','stdout 为格式化 {items:[...]} 或无执行说明；任一源达到 50 行时 stderr 警告。没有 --json：非空输出已是 JSON。'),p('For older runs or workflow steps use logs query/show and paginate. Missing script fails rather than returning a deceptive empty list. No remote mutation/cleanup.','旧执行/工作流步骤用 logs query/show 分页。脚本不存在则失败，不伪装空列表。无远程变更/清理。'),['demo_echo']);
add('script env','member',p('GETs dependency-environment state on the answering instance; --probe checks its package cache rather than merely recorded state. Does not install or run the script.','GET 回答实例的依赖环境状态；--probe 检查包缓存而非仅已记录状态。不安装、不执行脚本。'),p('Text describes key, packages, state (ready/building/failed/not built), installer error and optional probe; --json returns raw state. A reported failed environment is information, not necessarily a CLI nonzero exit.','文本含 key、包、状态（ready/building/failed/未构建）、安装错误与可选 probe；--json 返回原状态。环境 failed 是信息，不必然导致 CLI 非零退出。'),p('Query each node in a fleet; one response is not cluster readiness. Use script build to retry installation explicitly. Read/probe needs no undo.','多实例须逐节点查；单次响应不代表集群就绪。用 script build 显式重试安装。读取/探测无需撤销。'),['demo_echo','--json']);
add('script build','editor',p('Builds saved draft without publishing. Python/TypeScript warms dependency environment, reusing a single install; --wait polls. Rust compiles immediately; --wait is irrelevant. Binary reports manifest targets and locally held artifacts rather than compiling.','构建已保存草稿，不发布。Python/TypeScript 预热依赖、复用单次安装；--wait 轮询。Rust 立即编译，--wait 无意义。Binary 报告 manifest 目标与本实例 artifact，而非编译。'),p('Text reports environment/build; without --wait an install can still be running at exit 0. --wait exits 1 on failed install/timeout. Rust failure prints source diagnostics and rendered rustc output, exits 1.','文本报告环境/构建；不带 --wait 时退出 0 仍可在安装。--wait 安装失败/超时退出 1。Rust 失败打印源码诊断和 rustc 输出，退出 1。'),p('Requires a server with build capability/toolchain/package access; can install/download dependencies, so opt in explicitly. Retry with build after fixing dependencies, verify env on each node. Cached artifacts/environments are not removed by a CLI undo.','需服务端构建能力/工具链/包访问；可安装下载依赖，须明确允许。修复后 build 重试，逐节点 env 验证。无 CLI 撤销来删除环境/artifact。'),['demo_echo','--wait']);
add('script compile','editor',p('Local Rust-only compilation from server-provided exact crate and artifact key. Supply one name OR --all (published frozen programs, not drafts). --push uploads; default does not. --force bypasses already-present skip; SDK digest must match, from --sdk-path or VIAT_RUST_SDK_PATH.','仅本地 Rust 编译，使用服务端提供的精确 crate/artifact key。指定一个 name 或 --all（已发布冻结程序，不是草稿）。--push 才上传；默认不传。--force 绕过已有跳过；--sdk-path 或 VIAT_RUST_SDK_PATH 的 SDK digest 须匹配。'),p('Prints compilation/artifact/upload progress. --all continues across programs, reports failures and exits 1 if any failed. Existing artifact may yield a successful skip.','打印编译/artifact/上传进度。--all 逐个继续，报告失败，有任一失败退出 1。已有 artifact 可成功跳过。'),p('Needs local cargo/rustup, matching SDK and server OS/architecture; compilation may fetch crates. Upload additionally needs server artifact-upload enablement; changed artifact key refuses. Retain source/build diagnostics; remove disposable local build output if desired, not shared caches blindly.','需本地 cargo/rustup、匹配 SDK 与服务端 OS/架构；编译可下载 crate。上传另需服务端启用；artifact key 变化会拒绝。保留源码/诊断；按需清理演示构建输出，勿盲删共享缓存。'),['demo_rust','--sdk-path','./viat-sdk']);
add('script upload','editor',p('Binary-language only: reads nonempty executable, uploads bytes with update_manifest=1, then server records digest as a new draft revision. --target defaults to current CLI machine OS/arch, not remote detection; --folder disambiguates.','仅 binary 语言：读取非空可执行文件，以 update_manifest=1 上传；服务端随后把 digest 记为新草稿版本。--target 默认 CLI 机器 OS/架构，不探测远程；--folder 消歧。'),p('Prints byte count, target, digest, manifest revision change or unchanged, and pending endpoint list. Does not publish.','打印字节数、目标、digest、manifest 新版本或未变，以及待发布端点。不发布。'),p('Requires server upload enabled, compatible executable format and a binary manifest script. Wrong language/empty file/unsupported target fails. Inspect script show/build, publish intentionally; restore previous manifest and artifact for rollback (bytes are not retrieved by show).','需服务端允许上传、匹配可执行格式及 binary manifest 脚本。语言错误/空文件/不支持目标会失败。show/build 核查后有意发布；回退需旧 manifest 和 artifact（show 不取字节）。'),['demo_binary','--binary','./demo-worker','--target','linux/x86_64']);
add('script test','local',p('Runs local Python pytest via uv, TypeScript via bun test, and discovered Rust in-file tests. Default discovery uses tests/ and scripts/ for Rust. Uses matching-version viat-test-host with fake resources, not the signed-in server. User test code itself is not a network sandbox.','本地通过 uv 跑 Python pytest、bun test 跑 TypeScript，并跑发现的 Rust 内嵌测试。默认发现 tests/，Rust 用 scripts/。匹配版本 viat-test-host 提供假资源，不使用登录服务端。但用户测试代码本身不受网络沙箱限制。'),p('Streams runner output; --json captures a machine report with runner diagnostics on stderr. Propagates the aggregated nonzero test status. Missing prerequisites fail; no tests can print no tests found without proving coverage.','流式输出运行器结果；--json 捕获机器报告，诊断写 stderr。传播汇总非零测试状态。缺前提会失败；无测试可打印 no tests found，不代表覆盖。'),p('Install uv/bun/cargo only for tested languages plus matching host (VIAT_TEST_HOST_BIN override). TypeScript temporarily injects node_modules/viat and cleans it afterward. Inspect fixtures for external calls; remove generated local reports after review.','需相应语言 uv/bun/cargo 和匹配 host（VIAT_TEST_HOST_BIN 可覆盖）。TypeScript 临时注入 node_modules/viat 后清理。检查夹具是否外呼；审查后可删本地报告。'),['--json']);
